pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls in "dead zones"
    // (very small residuals that nothing will ever fit into) are penalized.
    let dead_zone = if post_residual < 10 { 1.0 } else { 0.0 };
    score += dead_zone * 60.0;

    // Perfect fit reward: post_residual in small harmonic classes near multiples.
    let harmonic = post_residual % 10;
    if harmonic == 0 && post_residual > 0 {
        score -= 25.0; // leftover is a usable decile
    } else if harmonic <= 2 {
        score += 15.0; // near-dead leftover
    }

    // Lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // chain-friendly: leftover still useful, mildly reward tightness
            score -= (post_residual - next_item_size) as f64 * 0.5;
            score -= 10.0;
        } else if post_residual > 0 {
            // leftover too small for next item: penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // Many open bins: encourage consolidation into tightest fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 0.15 * (1.0 - progress);

    // Deviation from mean residual: prefer bins tighter than average.
    score += (bin_residual as f64 - mean_residual) * 0.2;

    // New-bin candidate: only attractive when current bins are poor fits.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score = (bin_capacity as f64) - pressure * 200.0 - (fitting_bins_count as f64) * 30.0;
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 100.0;
        }
    }

    score
}

