// leftover after placement stays close to (but not below) the next item size, avoiding
// stranded slivers that inflate dead-space ratio.
if post_residual > 0 {
    let pr = post_residual as f64 ;
    if next_item_size > 0 {
        let nxt = next_item_size as f64 ;
        if pr < nxt {
            // leftover can't host next item: penalize proportional to unusable mass
            score += 4.0 * (nxt - pr) * (0.6 + 0.4 * (1.0 - progress)) ;
        } else {
            // leftover hosts next item: reward tightness around nxt with slight bias to smaller leftovers
            let over = pr - nxt ;
            score -= 3.0 * (1.0 - over / bin_capacity as f64) ;
        }
    }
    // mean-residual coupling: prefer bins whose post-residual tracks the fleet mean
    // (balances open bins, reduces many near-empty bins late in the stream)
    let mean = mean_residual.max(0.0) ;
    if mean > 0.0 && open_bins_count > 2 {
        let dev = (pr - mean).abs() ;
        score += 0.15 * dev * (0.5 + progress) ;
    }
}
// NEW: exact-fit lookahead — if post_residual equals a plausibly common size
// (small integer fraction of capacity), strongly reward.
if post_residual > 0 && bin_capacity % post_residual == 0 && post_residual <= bin_capacity / 2 {
    score -= 12.0 ;
}
score }

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest plausible future item (<= 10) are pure waste; penalize hard.
    if post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 8.0;
    } else if post_residual == 0 {
        // Perfect fit is ideal: strong reward.
        score -= 60.0;
    } else {
        // Smooth penalty for small-but-usable gaps that may become dead space.
        let tightness = 1.0 - (post_residual as f64) / 20.0;
        if post_residual < 20 {
            score += tightness * 12.0;
        }
    }

    // Reward bins whose residual can still accommodate the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
            // Bonus if post-residual is a tight, efficient host for next item.
            let slack = post_residual - next_item_size;
            if slack <= 8 {
                score -= 10.0;
            }
        } else {
            // Post residual cannot host next item: mild penalty scaled by gap.
            let gap = next_item_size - post_residual;
            score += (gap as f64).min(40.0) * 0.4;
        }
    }

    // Open-bin pressure: discourage spreading across many open bins when
    // this placement leaves a poor residual; encourage compacting.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (1.0 + mean_residual.max(1.0) / 10.0);
    score += pressure * (0.5 + 0.5 * progress);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless post residual is dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity && post_residual >= 10 {
        score -= 25.0;
    }

    // New-bin candidate: make empty bins attractive only when no open bin
    // offers a decent fit (i.e., all fits would leave dead space).
    if bin_residual == bin_capacity {
        // Neutral baseline slightly worse than a good existing fit.
        score = 25.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // New bin can host next item fully: slight edge.
            score -= 5.0;
        }
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64 * 0.95 ;
    let progress = step_index as f64 / total_items . max (1) as f64 ;
    if post_residual == 0 { score -= 1200.0 ; }
    if next_item_size > 0 && post_residual >= next_item_size {
        let tightness = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64 ;
        score -= 60.0 + 130.0 * tightness ;
        let two_step = post_residual . saturating_sub (next_item_size) ;
        if two_step >= item_size . min (next_item_size) { score -= 25.0 ; } else { score += 15.0 ; }
        if two_step == 0 { score -= 45.0 ; }
    }
    if post_residual > 0 && post_residual < 12 {
        score += 45.0 + 2.0 * (12 - post_residual) as f64 ;
        if next_item_size > post_residual { score += 20.0 ; }
    }
    let diff = (bin_residual as f64 - item_size as f64 - mean_residual) . abs () ;
    score += 0.15 * diff ;
    if fitting_bins_count == 1 && bin_residual < bin_capacity { score -= 50.0 ; }
    if fitting_bins_count > 2 { score += 0.4 * (bin_residual - item_size) as f64 ; }
    if progress < 0.4 { score += 0.25 * post_residual as f64 ; }
    else if progress > 0.85 { score += 0.5 * post_residual as f64 ; }
    if bin_residual == bin_capacity {
        score += 20.0 - 20.0 * (1.0 - progress) ;
        if fitting_bins_count == 0 { score -= 600.0 ; }
        else if item_size > bin_capacity / 2 && fitting_bins_count <= 2 { score -= 80.0 ; }
        else {
            let waste = (bin_residual - item_size) as f64 ;
            let nxt = next_item_size . max (1) as f64 ;
            if waste > 0.0 && waste < nxt { score -= 150.0 * (1.0 - waste / nxt) ; }
            else if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 { score += 30.0 + 0.3 * post_residual as f64 ; }
            else if item_size <= bin_capacity / 4 { score += 45.0 ; }
            else if waste > nxt { score += 25.0 ; }
        }
    }
    let dead = post_residual as f64 / bin_capacity as f64 ;
    if dead > 0.0 {
        let ideal = if next_item_size > 0 { next_item_size as f64 / bin_capacity as f64 } else { 0.0 } ;
        if dead < 0.35 { score += 105.0 * (0.35 - dead) ; }
        else if dead < 0.6 { let target = ideal . clamp (0.35 , 0.6) ; score += 25.0 + 60.0 * (dead - target) . abs () ; }
        else if dead < 0.85 { score += 8.0 ; }
    }
    if fitting_bins_count > 1 && next_item_size > 0 && post_residual == next_item_size { score -= 45.0 ; }
    if progress > 0.7 && open_bins_count > 4 {
        let fill = 1.0 - bin_residual as f64 / bin_capacity as f64 ;
        score -= 45.0 * fill ;
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size . min (item_size . max (1)) { score += 12.0 ; }
    if post_residual == item_size { score -= 85.0 ; }
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 6 { score -= 60.0 ; }
    if next_item_size > 0 && post_residual > next_item_size && post_residual < next_item_size + item_size { score += 18.0 ; }
    if post_residual > 0 && post_residual <= 4 { score += 30.0 ; }
    if next_item_size > 0 && item_size > 0 && post_residual >= next_item_size {
        let rem = post_residual - next_item_size ;
        if rem > 0 && rem < item_size && rem < 8 { score += 10.0 + 2.0 * (8 - rem) as f64 ; }
    }
    if next_item_size > 0 && post_residual > 0 {
        let gap = post_residual . saturating_sub (next_item_size) as f64 ;
        if gap > 0.0 && gap < 14.0 { score += 2.6 * (14.0 - gap) ; }
    }
    let fill_ratio = 1.0 - (bin_residual . saturating_sub (item_size)) as f64 / bin_capacity as f64 ;
    if fill_ratio > 0.9 { score -= 15.0 * (fill_ratio - 0.9) * 10.0 ; }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size { score += 1.5 * (next_item_size - post_residual) as f64 ; }
    if progress > 0.9 { score += 0.8 * post_residual as f64 ; }
    // lookahead: penalize leaving residual that fits neither current nor next item
    if next_item_size > 0 && post_residual > 0 && post_residual < item_size && post_residual < next_item_size {
        score += 25.0 + 0.5 * post_residual as f64 ;
    }
    // reward near-perfect compaction when residual exactly matches next item modulo small slack
    if next_item_size > 0 && post_residual > next_item_size {
        let slack2 = post_residual - next_item_size ;
        if slack2 <= 3 { score -= 20.0 + 5.0 * (3 - slack2) as f64 ; }
    }
    let score = score * 0.95 + diff * 0.05 ;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongest reward.
    if post_residual == 0 {
        score -= 1200.0;
    }

    // 2-step lookahead: reward when the next item fits the post residual,
    // with extra reward for near-perfect follow-up fits.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        let tightness = 1.0 - slack / bin_capacity as f64;
        score -= 60.0 + 120.0 * tightness;
        // If the item after next could also chain into the leftover slack,
        // give a small bonus (cheap greedy lookahead).
        if slack >= 1.0 && slack < 20.0 {
            score -= 8.0;
        }
    }

    // Penalize small dead space that likely becomes unusable,
    // scaled by how small it is relative to the next item.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
        if next_item_size > post_residual {
            score += 20.0;
        }
    }

    // Compare against mean residual: bins with residual close to item size are attractive.
    let diff = (bin_residual as f64 - item_size as f64 - mean_residual).abs();
    score += 0.25 * diff;

    // Last chance: strongly favor using this bin before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Early stream: prefer keeping large residual bins flexible.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.5 {
        score += 0.2 * post_residual as f64;
    } else {
        // Late stream: waste-averse — push harder toward tight fits.
        score += 0.1 * post_residual as f64;
    }

    // New-bin candidate handling: penalize unless genuinely needed or when
    // all fitting options leave substantial dead space.
    if bin_residual == bin_capacity {
        score += 20.0;
        if fitting_bins_count == 0 {
            score -= 600.0;
        } else {
            // If the best-fit alternative would waste a lot, opening a fresh
            // bin can be preferable for large incoming items.
            let best_alt_waste = post_residual; // item placed in an open bin
            if next_item_size > 60 && best_alt_waste > 25 {
                score -= 30.0;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 / (1.0 + diff);
        // Perfect match bonus
        if post_residual == next_item_size {
            score -= 30.0;
        }
        // Penalize residuals too small for next item (dead space for lookahead)
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
    }

    // Penalize unusable dead space: residual below minimum plausible item size
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 12.0 * (1.0 - progress * 0.5);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Penalize bins far from mean residual (prefer typical fill states),
    // but favor tight bins when residuals are small on average
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // New empty bin: discourage unless current bin would leave big dead space
    if bin_residual == bin_capacity {
        score += 18.0;
        // Allow new bin early in stream when it may pay off later
        score -= 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) via non-linear shaping.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * fit_ratio * 40.0;

    // Penalize leaving dead space that cannot fit the next item's lookahead.
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            // dead space: cannot host the next item
            score += (next_item_size - post_residual) as f64 * 0.6;
        } else if post_residual >= next_item_size {
            // bonus: bin remains useful for the lookahead item
            score -= 4.0 + 0.25 * next_item_size as f64;
        }
    } else {
        // Last item: just fill as much as possible
        score -= item_size as f64 * 0.3;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate logic: only attractive when the item fits poorly everywhere
    // or open bins are very full on average.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_fullness = 1.0 - mean_residual / bin_capacity as f64;
        // New bin gets a base penalty; reduced when open bins are congested.
        let mut new_bin_score = 55.0
            - 35.0 * avg_fullness
            - 10.0 * progress
            - 0.5 * open_bins_count as f64;
        // If item is large, a fresh bin is more acceptable.
        new_bin_score -= item_size as f64 * 0.15;
        // If no other bin fits, new bin is fine.
        if fitting_bins_count == 0 {
            new_bin_score -= 40.0;
        }
        score += new_bin_score;
    } else {
        // Reward using bins whose residual is close to the item (best-fit flavor).
        let tightness = 1.0 - (bin_residual - item_size) as f64 / bin_capacity as f64;
        score -= tightness * 12.0;

        // Mildly prefer bins with residual near mean (avoid fragmenting outliers).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.08;
    }

    // Late-stream pressure: consolidate more aggressively as the stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 6.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

