pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post residual, with non-linear sharpening
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, tolerate larger leftovers; late, penalize them more.
    score += 12.0 * norm_pr * progress * (1.0 - progress) * -1.0 * -1.0 * pr / (cap + 1.0);

    // Dead-space penalty: tiny leftovers are likely unusable
    if pr > 0.0 {
        let dead = (1.0 - pr / cap).max(0.0);
        score += 6.0 * (1.0 - (pr / 20.0).min(1.0)) * dead * (0.5 + progress);
    }

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 * (1.0 - norm_pr);
    }

    // New-bin candidate: penalize mildly so we prefer good existing fits,
    // but relax as stream progresses and open bins are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (open_bins_count as f64 / (mean_residual.max(1.0) / cap).max(0.1)).min(3.0);
        score = cap as f64 * (1.2 + 0.4 * progress) - 10.0 * fragmentation;
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        if next_item_size as f64 <= pr {
            score -= 8.0 * (next_item_size as f64 / cap);
        } else {
            score += 4.0 * ((next_item_size as f64 - pr) / cap);
        }
    }

    // Mean-residual coupling: bins far from the mean residual get a nudge
    score += 0.15 * (pr - mean_residual).abs() * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify leftover space into
    // capacity-fraction bands. Residuals in the "usable band" (>= 25% of
    // capacity) are less dead; tiny residuals are heavily penalized.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Dead-space penalty: quadratic blowup when post_residual is very small
    // but nonzero (wasted space that few future items can use).
    if post_residual > 0 && post_residual < bin_capacity / 10 {
        score += (cap / (post + 1.0)) * 2.5;
    }

    // Harmonic class reward via integer division thresholds:
    // post_residual falling in [C/4, C/2) is a "sweet spot" class.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if post_residual >= quarter && post_residual < half {
        score -= 12.0;
    } else if post_residual >= half {
        score -= 20.0;
    }

    // Modulo-arithmetic harmonic classes: pair the post-residual class with
    // the next item's class (sizes bucketed by 20s). Reward when the next
    // item would fit into the post-residual (chain potential).
    if next_item_size > 0 {
        let next_class = next_item_size / 20; // 0..5 harmonic bucket
        if next_item_size <= post_residual {
            // Next item chains nicely: reward proportional to bucket depth.
            score -= 8.0 + next_class as f64 * 2.0;
        } else {
            // Next item won't fit here: penalize more for finer classes
            // (large next items make big residuals valuable, small ones don't).
            score += next_class as f64 * 3.0;
        }
        // Exact modulo harmony: post_residual % next_class_size == 0 style bonus
        if next_item_size > 0 && post_residual % next_item_size.max(1) == 0 && post_residual > 0 {
            score -= 6.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin should only win when the
    // current bin's post-fit would be poor.
    if bin_residual == bin_capacity {
        // Base penalty so new bins are not opened frivolously.
        score += 25.0;
        // But if the item is large (hard to place later), a fresh bin is fine.
        if item_size > bin_capacity / 2 {
            score -= 15.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Prefer filling bins that are already relatively full (small residual
    // relative to mean): best-fit tilt.
    if mean_residual > 0.0 {
        let rel = bin_residual as f64 / mean_residual;
        if rel < 1.0 {
            score -= (1.0 - rel) * 10.0;
        } else {
            score += (rel - 1.0) * 5.0;
        }
    }

    // Slight pressure against keeping many bins open with large residuals.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=12) are heavily penalized.
    if post_residual > 0 && post_residual <= 12 {
        score += 40.0 * (13.0 - post_residual as f64);
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Moderate gaps are mildly penalized if the lookahead item cannot use them.
    if next_item_size > 0 && post_residual >= 13 && post_residual < next_item_size {
        score += 8.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Gap usable by the next item: reward keeping this bin.
        score -= 10.0;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // Open-bins pressure: discourage opening new bins when many bins are open,
    // but relax late in the stream.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    let new_bin_penalty = 55.0 * (1.0 - 0.4 * progress);
    if bin_residual == bin_capacity {
        score += new_bin_penalty;
        // Opening a new bin is attractive only if the item leaves a big residual
        // that could serve future items, and few bins are open.
        if post_residual >= 60 && open_bins_count < 3 {
            score -= 30.0;
        }
    }

    // Prefer bins with residual close to item_size (tight fit) relative to mean residual.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 20.0 * tightness;

    // Slight preference for bins below mean residual (consolidating fuller bins).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: this bin's leftover exactly fits the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Leftover still usable for next item: mild reward proportional to slack.
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Dead space relative to next item: penalize proportionally to waste.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.9 * waste;
        }
    } else {
        // Last item: prefer tightest fit overall.
        score += 0.5 * post_residual as f64;
    }

    // Prefer bins with residuals below the mean (consolidate large holes),
    // penalize dipping far below mean residual.
    score += 0.35 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize leaving tiny unusable slivers (dead space < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Early in the stream, be more willing to keep bins tight; later, favor
    // closing out bins to reduce open-bin count.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Mild preference for filling already-open bins vs. proliferating bins.
    score += 0.02 * open_bins_count as f64;

    // New-bin candidate: only attractive when it enables a perfect next-item match
    // (residual 100 >= next_item_size) or nothing reasonable fits otherwise.
    if bin_residual == bin_capacity {
        if next_item_size > 0 && (100 - item_size as u32) == next_item_size {
            score -= 40.0;
        } else {
            score += 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (low post residual is already rewarded by base).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful for typical items:
    // residuals in (0, 10] are nearly unusable; residuals >= 10 can host min-size items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // heavily reward this placement (perfect chain).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 4.0;
        } else {
            // Next item won't fit here; mild penalty proportional to leftover waste.
            score += 2.0;
        }
        // If next item is large, prefer keeping bins with big residuals for it.
        if next_item_size >= 60 && post_residual < next_item_size {
            score += 3.0;
        }
    }

    // Last-chance logic: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the item
    // fits poorly everywhere else. Make the empty bin moderately expensive by default.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Early stream: opening bins is cheap (builds a portfolio); late stream: expensive.
        score += 12.0 * (1.0 - progress) + 8.0 * progress;
        // If many bins are open, discourage proliferation.
        score += 0.4 * open_bins_count as f64;
        // If mean residual is large, plenty of room exists; discourage a new bin.
        score += 0.15 * mean_residual;
        // Exception: huge items (>= 70) deserve a fresh bin if nothing tight exists.
        if item_size >= 70 {
            score -= 10.0;
        }
    }

    // Global state: when mean residual across open bins is high, prefer bins that
    // reduce variance (i.e., below-mean residuals get filled first).
    if bin_residual as f64 > mean_residual {
        score += 1.5;
    } else {
        score -= 1.5;
    }

    // Slight preference for filling bins that are already quite full (consolidation).
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 3.0 * fill_ratio;

    // Time horizon: as the stream ends, waste minimization matters more; tighten scoring.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;
    // smooth polynomial coupling of post-residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * (1.0 - norm_pr);
    score += 12.0 * poly;
    // penalize dead space more as stream progresses
    score += progress * norm_pr * norm_pr * cap * 0.5;
    // reward tight fits (small post residual)
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * item_size as f64 * 0.3;
    // last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 8.0 + 10.0 * progress;
    }
    // lookahead: favor bins leaving room for next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr >= ns {
            score -= 5.0 * (1.0 - ((pr - ns) / cap).abs());
        } else {
            score += 3.0 * (ns - pr) / cap;
        }
    }
    // prefer bins below mean residual (consolidating space)
    score += 0.4 * (pr as f64 - mean_residual);
    // new-bin candidate: penalize mildly so it's chosen only for poor fits
    if bin_residual == bin_capacity {
        score += 15.0 - 10.0 * progress + 0.05 * open_bins_count as f64;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize dead space into capacity fractions.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // 0.0 .. 1.0

    // Dead-space bands: residuals that are hard to fill (small leftovers) are penalized.
    // Residuals in "useful" bands (>= 25% capacity) are rewarded.
    if post_residual == 0 {
        score -= 60.0; // perfect fit, best outcome
    } else if post_residual <= 10 {
        score += 25.0; // tiny unusable dead space
    } else if post_residual <= 20 {
        score += 12.0; // awkward dead space
    } else if post_residual <= 50 {
        score -= 8.0; // sweet spot: room for medium items
    } else {
        score -= 15.0; // large residual left, still very usable
    }

    // Modulo arithmetic on post_residual: harmonics of common item sizes.
    // Residuals divisible by 10 or 5 pair well with typical item sizes.
    if post_residual % 10 == 0 {
        score -= 6.0;
    } else if post_residual % 5 == 0 {
        score -= 3.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 14.0;
        if post_residual % next_item_size == 0 {
            score -= 10.0; // exact harmonic split possible
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 8.0; // next item won't fit here; this bin becomes dead unless residual small
    }

    // Last-chance logic: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid fragmentation).
    if fitting_bins_count <= 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current bin
    // would leave very poor residual AND many bins are already open.
    if bin_residual == bin_capacity {
        // Brand-new bin: score is its full capacity minus bonuses.
        score = cap;
        // Early in the stream, opening bins is cheap; later, prefer filling.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // If many bins open with large mean residual, opening another is wasteful.
        score += 0.5 * open_bins_count as f64;
        if mean_residual > 30.0 {
            score += 15.0;
        }
        // But if the current placement would strand space, new bin becomes attractive:
        // (handled implicitly since real-bin scores get dead-space penalties)
        if next_item_size > 0 && next_item_size > item_size {
            score -= 5.0; // big item coming; fresh bin may help
        }
    }

    // Tight-fit reward: item nearly fills the bin.
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    if tightness > 0.9 {
        score -= 20.0;
    } else if tightness > 0.7 {
        score -= 6.0;
    }

    // Mild preference for fuller bins overall (best-fit core bias).
    score -= 0.1 * (cap - post) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below 10 are unusable (min item = 10... but sizes can be 1)
    let dead_threshold = 9.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += 40.0 + (dead_threshold - post_residual as f64) * 8.0;
    }

    // Reward tight fits: waste ratio relative to item size
    let waste_ratio = post_residual as f64 / (item_size.max(1) as f64);
    score -= 12.0 / (1.0 + waste_ratio);

    // Penalize mid-range residual gaps that are hard to fill later
    if post_residual > 10 && post_residual < 30 {
        score += 6.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins exist
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if current bin would leave dead space
        score += 5.0 + open_bins_count as f64 * 0.5;
        if post_residual == 0 {
            score -= 50.0; // exact fit handled elsewhere, but keep safe
        }
    } else {
        score -= 2.0 + 3.0 / (1.0 + open_bins_count as f64);
    }

    // Last-chance bin bonus: avoid wasting the only fitting bin's space
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // Lookahead: if next item fits the post residual, reward this placement
    if next_item_size > 0 && (post_residual as i64 - next_item_size as i64) >= 0 {
        score -= 6.0;
    }
    if next_item_size > 0 && post_residual > 0 && (post_residual as i64 - next_item_size as i64) < 0 {
        score += 4.0; // next item won't fit here; residual likely dead
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins first)
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Early stream: be more conservative about filling bins tightly
    score += 3.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space that is too small to hold typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 2-step lookahead: strongly reward bins whose post_residual exactly or
    // nearly fits the next item (chaining placements).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect chain: bin fully consumed in two steps
        } else if next_item_size <= post_residual {
            // next item fits: reward proportionally to how little slack remains after
            let chain_slack = (post_residual - next_item_size) as f64;
            score -= 40.0 - chain_slaw(chain_slack);
        } else {
            // next item does not fit in the leftover: penalize wasted lookahead potential
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap;
        }
    }

    // Compare post_residual against the mean residual across open bins:
    // favor bins that end up tighter than average (good consolidation),
    // penalize bins that stay loose while others are tight.
    score += 0.30 * (post_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: make an empty bin attractive only when the
    // item is large (few bins can hold it later) or no existing bin chains well.
    if bin_residual == bin_capacity {
        let tight_fit = (item_size as f64 / bin_capacity as f64) > 0.6;
        let no_chain = next_item_size == 0 || next_item_size > post_residual;
        if tight_fit && no_chain {
            score -= 30.0; // opening fresh space is fine for big items
        } else {
            score += 20.0; // discourage wasting a fresh bin on small items
        }
    }

    // Late in the stream, consolidation matters more: prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Mild penalty per open bin: fewer bins is better, favor bins that close out.
    if post_residual == 0 {
        score -= 50.0; // perfectly filled bin
    }

    score
}

// small helper shaping the chain reward (concave in slack)
#[inline]
fn chain_slaw(slack: f64) -> f64 {
    slack.sqrt() * 4.0
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: normalize post residual by capacity.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 15.0 * fit_ratio * fit_ratio;

    // Reward near-exact fills (post_residual very small).
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: bonus if the next item fits exactly in the post residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 18.0;
        } else if post_residual > next_item_size {
            score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item cannot fit here; slight penalty for leaving medium gaps.
            score += 4.0;
        }
    }

    // Time horizon: early in stream, be conservative with open bins (favor filling);
    // late in stream, allow opening new bins more freely.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * (1.0 - progress);

    // Penalize bins whose residual deviates far below the mean residual
    // (they are already well used; prefer spreading load evenly).
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 5.0 * dev;

    // New-bin candidate: baseline discouragement, weaker when many bins are open
    // or the item is large relative to capacity.
    if bin_residual == bin_capacity {
        let large_item_bonus = item_size as f64 / bin_capacity as f64;
        score = 60.0 - 25.0 * large_item_bonus - 10.0 * progress;
        // If no open bin fits well, opening a new bin is fine.
        if fitting_bins_count == 0 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Penalize small-but-nonzero post_residual (dead space), smooth via polynomial
    let dead = norm_pr * (1.0 - norm_pr);
    score += 40.0 * (1.0 - 4.0 * dead) * (1.0 - progress);

    // Reward tight fits (low post_residual relative to item)
    score -= 30.0 * norm_item * (1.0 - norm_pr);

    // Last-chance bonus when only one bin fits
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let need = next_item_size as f64;
        let fit = ((pr - need).max(0.0)) / cap;
        score -= 20.0 * fit * (1.0 - fit * fit);
    } else {
        score += 0.0;
    }

    // Mild pressure toward consolidating bins as many open bins accumulate
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    // Deviation from mean residual: prefer bins near/below mean residual
    score += 0.2 * (pr - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of the leftover space: classify post_residual by
    // division into capacity fractions (quarters / thirds / eighths).
    let pr = post_residual as f64;
    let frac = pr / cap; // fraction of capacity wasted after placement

    // Penalize leftovers that fall into "dead zone" classes:
    // class A: (0, 10)  -> unusable by the smallest items
    // class B: [10, 25) -> barely usable, low value
    // class C: [25, 50) -> moderately usable
    // class D: >= 50    -> flexible space
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // worst class: near-dead space
    } else if post_residual < 25 {
        score += 20.0;
    } else if post_residual < 50 {
        score -= 10.0;
    } else {
        score -= 20.0;
    }

    // Integer-division harmonic class of next_item_size vs post_residual:
    // does the next item divide into the leftover cleanly?
    if next_item_size > 0 {
        let n = next_item_size;
        if n <= post_residual {
            // how many times does next item fit into the leftover?
            let k = post_residual / n;
            let rem = post_residual % n;
            // prefer leftovers that admit an integer number of next items
            if rem == 0 && k >= 1 {
                score -= 25.0;
            } else {
                score += rem as f64 * 0.5;
            }
            // next item exactly fills the bin -> strong bonus
            if post_residual == n {
                score -= 40.0;
            }
        } else {
            // next item cannot use this leftover: penalize proportionally
            score += (n - post_residual) as f64 * 0.3;
        }
    }

    // Modulo-10 harmonic structure (typical size quantum):
    // leftovers that are multiples of 10 are more reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 15.0;
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is huge
    // or existing leftovers are all in dead classes.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut penalty = 120.0;
        if item_size >= 50 {
            penalty -= 40.0; // big items justify fresh space
        }
        if mean_residual < 15.0 {
            penalty -= 60.0; // open bins are nearly dead anyway
        }
        penalty *= 1.0 - 0.3 * progress;
        score += penalty.max(0.0);
    }

    // Mild preference for tighter bins overall
    score += (bin_residual as f64 - mean_residual) * 0.1;

    // Small tie-break: prefer bins whose residual is close to item size
    score += ((bin_residual as f64 - item_size as f64) / cap).abs() * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no plausible item can fill are heavily penalized.
    if post_residual > 0 {
        // A gap is "dead" if it is smaller than the smallest item (assume min item ~ 10,
        // but be conservative for unknown distributions: treat < 5 as certainly dead,
        // and < 12 as risky).
        if post_residual < 5 {
            score += 200.0;
        } else if post_residual < 12 {
            score += 60.0 * (12.0 - post_residual as f64);
        } else {
            // Usable gap: reward leaving room proportional to its usefulness,
            // but prefer gaps that exactly match the lookahead item.
            score -= 8.0;
        }
    } else {
        // Perfect fill: strong reward.
        score -= 120.0;
    }

    // Lookahead coupling: reward a post_residual that lets the next item fit exactly or well.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 90.0;
        } else if post_residual >= next_item_size {
            score -= 20.0 * (1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64));
        } else {
            // Next item cannot use this bin's leftover: mild penalty scaled by tightness.
            score += 15.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the dead-space penalty above is severe).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 70.0;
    }

    // Open-bin pressure: discourage proliferation of bins when few are open,
    // and discourage stuffing when many bins are already open.
    let open_pressure = (open_bins_count as f64).ln().max(0.0) * 10.0;
    score += open_pressure;

    // New-bin candidate handling: an empty bin has huge residual; make it attractive
    // only when the current item is large and would leave a big usable gap anyway,
    // or when no good fit exists. Base cost of opening a new bin:
    if bin_residual == bin_capacity {
        score += 45.0;
        // Large items benefit from a fresh bin (they leave flexible space).
        if item_size >= 60 {
            score -= 55.0;
        }
        // If many bins are open and residuals are fragmented, fresh bin is fine.
        if mean_residual < 25.0 && open_bins_count > 3 {
            score -= 30.0;
        }
    }

    // Mild stream-progression bias: late in the stream, tighten packing (prefer exact fits
    // even more) since fewer future items remain to fill leftover gaps.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * (post_residual as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongest reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when the next item fits the post residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let tightness = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 50.0 + 100.0 * tightness;
    }

    // Penalize small dead space (< 10) that likely becomes unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Compare against mean residual: bins with residual close to item size are attractive.
    let diff = (bin_residual as f64 - item_size as f64 - mean_residual).abs();
    score += 0.3 * diff;

    // Last chance: strongly favor using this bin before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Early stream: prefer keeping large residual bins flexible.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.5 {
        score += 0.2 * post_residual as f64;
    }

    // Discard new-bin preference unless it's genuinely needed (empty-bin candidate
    // gets penalized slightly so only poor fits trigger it).
    if bin_residual == bin_capacity {
        score += 15.0;
        // But if no open bin fits, allow opening a new bin.
        if fitting_bins_count == 0 {
            score -= 500.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core tight-fit reward: heavily discount bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 60.0 * fit_ratio * fit_ratio;

    // Penalize leaving awkward dead space (small post_residual that can't hold typical items).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here anyway; mild penalty for wasting residual
            score += 5.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin is attractive when the item is large
    // and fits poorly everywhere else, or late in the stream with few open bins.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a bin: cheaper early (long horizon to amortize), costlier late.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 + 50.0 * progress;

        // If item is large, a fresh bin wastes little; encourage it.
        score -= 0.4 * item_size as f64;

        // If many bins fit the item, opening a new one is less necessary.
        score += 8.0 * fitting_bins_count as f64;
    } else {
        // Prefer reusing bins with larger residuals (keep small-residual bins for small items).
        score += 0.05 * (bin_capacity as f64 - bin_residual as f64);

        // Slight preference for bins below mean residual (balance load).
        if (bin_residual as f64) > mean_residual {
            score += 3.0;
        }
    }

    // Late-stream: discourage fragmentation, favor bins that end near-empty waste minimal.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.8 && post_residual > 0 {
        score += 0.1 * post_residual as f64 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base: prefer small post-residual, with a quadratic penalty on wasted space.
    let mut score = post + 0.35 * (post / cap) * post;

    // Smooth coupling: as the stream progresses, tight fits matter more.
    let tight = 1.0 - post / cap; // 0 = empty, 1 = full
    score -= progress * 8.0 * tight * tight;

    // Penalize leaving a residual that is too small for typical future items
    // (dead space), smoothly weighted by how close post_residual is to a
    // small unusable gap.
    let gap = post / cap;
    score += 6.0 * gap * (1.0 - gap) * (1.0 - gap);

    // Interaction: item size vs post residual — reward large items filling bins.
    score -= 4.0 * (item / cap) * (item / cap) * tight;

    // Lookahead: if the next item fits exactly into the post residual, reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_diff = (post - nxt).abs();
        score -= 5.0 * (1.0 - fit_diff / cap) * (1.0 - fit_diff / cap);
        // Penalize if post residual can't hold next item at all (fragmentation).
        if post < nxt {
            score += 3.0 * (1.0 - post / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else if fitting_bins_count > 1 {
        // Spread load when many bins fit; slight penalty for always cramming.
        score += 0.6 * (fitting_bins_count as f64).ln();
    }

    // Mean residual context: prefer bins deviating favorably from the mean
    // (place into below-average-residual bins to consolidate fullness).
    score += 0.05 * (mean_residual - post);

    // New-bin candidate handling: empty bin gets a smooth opening cost that
    // shrinks as the stream progresses or when few bins fit the item.
    if bin_residual == bin_capacity {
        let open_cost = 40.0 * (1.0 - progress) * (1.0 - item / cap);
        score += open_cost;
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of post_residual: residues divisible by large common
    // item sizes (e.g. multiples of 10/20/25) are "usable" future slots.
    let pr = post_residual;
    let harmonic_bonus: f64 = if pr == 0 {
        -30.0 // perfect closure
    } else if pr % 50 == 0 {
        -12.0
    } else if pr % 25 == 0 {
        -8.0
    } else if pr % 20 == 0 {
        -6.0
    } else if pr % 10 == 0 {
        -4.0
    } else if pr < 10 {
        15.0 // dead space: nothing can ever fit
    } else {
        0.0
    };
    score += harmonic_bonus;

    // Lookahead coupling: reward if next item fits exactly or well into post_residual.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 20.0; // chain closure
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / cap);
        } else {
            // next item won't fit here: mild penalty scaled by excess
            score += 0.05 * (n - post);
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: only attractive when current fit is poor and
    // mean residual across open bins is already large.
    if bin_residual == bin_capacity {
        let tightness = (item_size as f64) / cap;
        let poor_fit = (bin_residual - item_size) as f64 / cap;
        let pressure = mean_residual / cap;
        score = 25.0 + 40.0 * (1.0 - tightness) - 20.0 * pressure - 10.0 * poor_fit;
        if next_item_size > 0 && next_item_size <= bin_capacity / 2 {
            score -= 5.0;
        }
    }

    // Fractional refinement: penalize post_residual in awkward mid-range bands.
    let frac = post / cap;
    if frac > 0.05 && frac < 0.10 {
        score += 6.0;
    }

    // Progress term: late in the stream, prefer closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * progress * (1.0 - frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are tiny but nonzero are
    // effectively unusable -> penalize them super-linearly.
    if post_residual > 0 {
        let gap = post_residual as f64;
        if gap < 12.0 {
            score += (12.0 - gap) * 6.0; // hard penalty for near-dead slivers
        } else if gap < 25.0 {
            score += (25.0 - gap) * 1.5; // soft penalty for awkward small gaps
        }
        // Reward near-perfect fills (very small waste is fine, already low base).
        if gap <= 3.0 {
            score -= 8.0;
        }
    } else {
        // Perfect fit: strongest reward.
        score -= 20.0;
    }

    // Open-bin pressure: prefer consolidating into existing bins when many
    // bins are open; allow new bins when few are open.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when bin count is already high,
        // but relax when current fit landscape is crowded/poor.
        score += 15.0 + 10.0 * pressure;
        if fitting_bins_count <= 1 && post_residual > 0 {
            // No good existing option? make new bin less unattractive.
            score -= 12.0;
        }
        if next_item_size > 0 && (next_item_size as f64) > mean_residual {
            // Lookahead: next item may not fit open bins anyway.
            score -= 6.0;
        }
    } else {
        // Existing bin: reward using it, especially when many bins are open.
        score -= 4.0 + 2.0 * pressure;
        // Last-chance bin: strongly prefer filling it rather than wasting it.
        if fitting_bins_count == 1 {
            score -= 10.0;
        }
        // Lookahead synergy: if the next item exactly fits the post-residual,
        // this placement sets up a chain of perfect fits.
        if next_item_size == post_residual && post_residual > 0 {
            score -= 9.0;
        }
        // Penalize placements into bins whose residual is far from mean
        // (keeps residual distribution balanced for future items).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: if the next item fits exactly in the post-residual,
    // this is a perfect chain placement -> strong reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 - gap / bin_capacity as f64);
        if gap == 0.0 {
            score -= 30.0; // exact 2-item chain
        }
    } else if next_item_size > 0 {
        // Next item won't fit: penalize dead space relative to next item size.
        score += 0.5 * (next_item_size as f64 - post_residual as f64).min(60.0);
    }

    // Reward tight fits now (small post_residual relative to bin capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 20.0 * tightness * tightness;

    // Relative-to-mean coupling: bins with residual below mean are "valuable" fills.
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Last chance: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless post_residual would be tiny dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 0.2 * post_residual as f64;
    }

    // New-bin candidate handling: opening a new bin is only attractive early
    // in the stream or when the current fit is very loose.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let loose = item_size as f64 / bin_capacity as f64;
        score += 30.0 * (1.0 - progress) - 25.0 * loose;
        // discourage new bins when many bins are open and one fits well
        if fitting_bins_count > 0 && post_residual as f64 > 0.15 * bin_capacity as f64 {
            score += 15.0;
        }
    }

    // Mild penalty for very large dead space that likely becomes unusable.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward small post_residual non-linearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * fit_ratio * 40.0;

    // Penalize leaving dead space that cannot fit typical upcoming items.
    if post_residual > 0 && (next_item_size == 0 || post_residual < next_item_size as f64) {
        score += 15.0;
    }

    // Lookahead synergy: if the next item fits the post residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size as u32 {
        score -= 12.0 + 0.1 * next_item_size as f64;
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Time horizon: early in the stream, be more willing to open new bins
    // (favor spreading); late in the stream, consolidate tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin_bias = 20.0 * (1.0 - progress);
    if bin_residual == bin_capacity {
        score -= new_bin_bias;
        // Opening a new bin is good when open bins are fragmented (high mean residual)
        score -= (mean_residual / bin_capacity as f64) * 10.0;
    } else {
        // Reward using existing bins when mean residual is low (tight packing phase)
        score += (mean_residual / bin_capacity as f64) * 8.0 * progress;
    }

    // Slight preference for fuller bins among candidates.
    score -= (bin_residual as f64 / bin_capacity as f64) * 5.0;

    // Mild penalty for proliferating bins mid-stream.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64).sqrt() * 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let t = step_index as f64 / total_items.max(1) as f64;

    // Smooth polynomial coupling of post_residual with stream progress.
    let norm_pr = pr / cap;
    score += 12.0 * norm_pr * norm_pr * (0.5 + t);
    score -= 6.0 * norm_pr * (1.0 - t) * (1.0 - t);

    // Reward tight fits more as stream progresses (quadratic in fill ratio).
    let fill = (item_size as f64) / cap;
    score -= 10.0 * fill * fill * (0.3 + 0.7 * t);

    // Penalize dead space far from mean residual (smooth quadratic coupling).
    let dev = pr - mean_residual;
    score += 0.02 * dev * dev / (1.0 + t);

    // Last-chance bonus: strongly favor the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - norm_pr);
    }

    // Lookahead: reward bins whose post-residual accommodates next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 4.0 * (nx / cap) * (1.0 - t * 0.5);
        } else {
            let waste = (nx - pr) / cap;
            score += 5.0 * waste * waste;
        }
    }

    // Mild penalty for bin proliferation early in the stream.
    score += (open_bins_count as f64).ln() * (1.0 - t) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: post_residual classes mod 10.
    // Residuals in 1..=9 are "dead space" classes; 0 is perfect fit.
    let pr = post_residual as i64;
    let class = pr % 10;
    if class == 0 {
        score -= 60.0; // perfect harmonic fit
    } else if class <= 5 {
        // small dead space: hard to fill later (items >= 10)
        score += 12.0 * (6 - class) as f64;
    } else {
        // residual 6..=9: nearly useless
        score += 18.0 + (10 - class) as f64;
    }

    // Integer-division thresholds: how many size-10 quanta remain
    let quanta = post_residual / 10;
    score -= 4.0 * quanta as f64;

    // Coupling with next item: does it fit in post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // chain fit: strong reward, scaled by leftover after next item
            let nr = (post_residual - next_item_size) as f64;
            score -= 25.0 - 0.2 * nr;
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 15.0; // chained harmonic perfection
            }
        } else {
            score += 10.0; // next item cannot follow here
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
