        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual > next_item_size && (post_residual - next_item_size) < 10 {
            score -= 8.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            // residual too small for the next item: mild penalty
            score += 4.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin wastes the residual of this bin.
    if bin_residual == bin_capacity {
        // Attractive when open-bin pressure is low or residual is fragmented;
        // discouraged when many bins are open (consolidation pressure).
        score += open_bins_count as f64 * 3.0;
        // If current bin is the only fitting bin, opening a new bin is bad
        if fitting_bins_count == 1 {
            score += 40.0;
        }
        // Late in the stream, prefer consolidating into existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
    }

    // Open-bins pressure: with many open bins, favor bins below-mean residual
    // (fill down the most-filled bins to free up bins faster).
    score += open_bins_count as f64 * 0.5;
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += (bin_residual as f64 - mean_residual) * 0.3;
    }

    // Penalize large leftover waste proportionally (quadratic dead-space coupling)
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: reward heavily.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when the next item exactly fills the post residual.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            // Next item fits, but leaves a smaller residual: mild reward scaled by tightness.
            let slack = (post_residual - next_item_size) as f64;
            score -= 150.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Dead space: next item cannot use the leftover; penalize proportionally,
            // worse when the leftover is small (unusable) and near the end of stream.
            let waste = post_residual as f64;
            let progress = step_index as f64 / total_items.max(1) as f64;
            score += waste * (0.5 + 0.5 * progress);
        }
    }

    // Penalize creating tiny unusable residuals (< 10, the minimum item size).
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    }

    // Compare against mean residual: prefer bins whose post residual stays near the mean
    // (balanced packing), penalize outliers.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    score += 0.5 * open_bins_count as f64;

    // New-bin candidate: make the empty bin attractive only when the fit is poor.
    if bin_residual == bin_capacity {
        let good_fit = post_residual == 0
            || (next_item_size > 0 && next_item_size == post_residual);
        if good_fit {
            score += 50.0; // still slightly worse than a perfect existing fit
        } else {
            score += 500.0 + 3.0 * post_residual as f64;
        }
    }

    score
}

