        // Late stream: waste-averse — push harder toward tight fits.
        score += 0.5 * post_residual as f64;
    }

    // New-bin candidate handling: penalize unless genuinely needed or when
    // all fitting options leave substantial dead space.
    if bin_residual == bin_capacity {
        score += 20.0;
        if fitting_bins_count == 0 {
            score -= 600.0;
        } else if item_size > bin_capacity / 2 && fitting_bins_count <= 2 {
            // Large item with few alternatives: opening a fresh bin is often better.
            score -= 80.0;
