                // Placement strands residual below next item's size: favor new bin.
                score += 30.0 + 0.3 * post_residual as f64;
            }
        }
    }

    // Dead-space ratio shaping: avoid leaving slivers, target usable chunks.
    let dead = post_residual as f64 / bin_capacity as f64;
    if dead > 0.0 {
        let ideal = if next_item_size > 0 {
            next_item_size as f64 / bin_capacity as f64
        } else {
            0.0
        };
        if dead < 0.35 {
            score += 90.0 * (0.35 - dead);
        } else if dead < 0.6 {
            let target = ideal.clamp(0.35, 0.6);
            score += 25.0 + 60.0 * (dead - target).abs();
        } else if dead < 0.85 {
            score += 8.0;
        }
    }

    // Late stream with many open bins: reward deeper fills to close bins out.
    if progress > 0.7 && open_bins_count > 4 {
        let fill = 1.0 - bin_residual as f64 / bin_capacity as f64;
        score -= 30.0 * fill;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on wasted space ratio.
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += 60.0 * waste_ratio * waste_ratio;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Small dead space (< smallest plausible item) is nearly worthless.
    if post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit_tightness = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - next_fit_tightness / bin_capacity as f64);
    }
    // If next item cannot fit here anyway, mild penalty for leaving large gap it can't use.
    if next_item_size > 0 && post_residual < next_item_size && post_residual >= 10 {
        score += 8.0;
    }

    // Penalize opening new bins when many bins are already open (consolidation pressure).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 20.0 + 2.0 * open_bins_count as f64;
        // Early in stream, new bins are cheaper; late in stream, consolidate.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
        // If mean residual across open bins is large, opening a new bin wastes potential.
        score += 0.5 * mean_residual;
        // If this bin is the only one that fits, override: don't open new bin.
        if fitting_bins_count == 1 {
            score += 200.0;
        }
    } else {
        // Reward using bins with residual close to item (best-fit bias beyond post_residual).
        let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
        score -= 10.0 * (1.0 - tightness);
    }

    // Slight preference for bins below mean residual (balance residuals).
    if !is_new_bin {
        let diff = bin_residual as f64 - mean_residual;
        score += 0.05 * diff;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: prefer minimal leftover space (tight fit), with a convex penalty
    // on large dead space so mid-size gaps are discouraged quadratically.
    let mut score = post * (1.0 + 0.8 * norm_post * norm_post);

    // Smooth polynomial coupling of dead space with stream progress:
    // late in the stream, wasted space becomes progressively more costly.
    let progress_coupling = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += 25.0 * progress_coupling * norm_post * (1.0 - norm_post);

    // Perfect fit reward: subtract strongly as post_residual approaches zero,
    // with a smooth (1 - norm_post)^4 falloff.
    score -= 40.0 * (1.0 - norm_post).powi(4);

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 * (1.0 - progress_coupling * 0.5);
    }

    // New-bin candidate handling: score a fresh bin by its potential to pair
    // with the lookahead item. Smooth interaction between item size and
    // future space, coupled with mean residual across open bins.
    if bin_residual == bin_capacity {
        let next = next_item_size as f64;
        let pairing = if next > 0.0 {
            // reward a new bin if next item would pair well with the space
            // this item leaves (post_residual close to next_item_size).
            let gap = (post - next).abs() / cap;
            20.0 * (1.0 - gap).powi(2) - 10.0 * gap
        } else {
            -5.0 * progress // end of stream: fresh bins are cheap
        };
        score = post + pairing + 3.0 * (open_bins_count as f64).sqrt() * (1.0 - progress);
    } else {
        // Mild penalty when this bin's residual deviates far from the mean
        // residual, encouraging residual homogenization across open bins.
        let dev = (bin_residual as f64 - mean_residual) / cap;
        score += 5.0 * dev * dev;
    }

    // Lookahead: if the next item exactly fills this bin's post space,
    // give a smooth bonus proportional to the match quality.
    if next_item_size > 0 {
        let match_q = 1.0 - ((post - next_item_size as f64).abs() / cap);
        if match_q > 0.0 {
            score -= 15.0 * match_q * match_q * match_q;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base tightness: reward small post_residual super-linearly.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Harmonic classes: quantize post_residual into capacity-fraction buckets.
    // Residuals in the "useless zone" (too small for typical items) are penalized.
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    if post_residual > 0 && post_residual <= eighth {
        // Dead space class: residual can likely never be reused.
        score += 40.0 + (eighth - post_residual) as f64;
    } else if post_residual <= quarter {
        // Marginal class: only fits tiny items.
        score += 12.0;
    } else if post_residual <= 2 * quarter {
        // Half class: decent reusability, mild reward.
        score -= 6.0;
    } else {
        // Large residual class: very reusable.
        score -= 10.0;
    }

    // Modular arithmetic on post_residual: residuals divisible by common item
    // sizes (and their complements) are more likely to be filled later.
    if post_residual > 0 {
        let mut div_bonus = 0.0;
        for d in [10u32, 20, 25, 50] {
            if post_residual % d == 0 {
                div_bonus += 4.0;
            }
        }
        score -= div_bonus;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward this bin (perfect chain).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // Next item fits but leaves a new residual: evaluate chain quality.
            let chain_res = post_residual - next_item_size;
            score -= 8.0 - (chain_res.min(30)) as f64 * 0.1;
        } else {
            // Next item cannot use this bin's residual: slight penalty.
            score += 5.0;
        }
    }

    // Last-chance logic: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // item fits poorly everywhere else. Penalize new bins mildly by default,
    // but discount the penalty late in the stream or when many bins are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_penalty = 18.0;
        if next_item_size > 0 && next_item_size > post_residual {
            // Item won't chain here anyway; new bin slightly less bad.
            new_bin_penalty -= 5.0;
        }
