    // it is an outlier worth consolidating into (or avoiding if it creates waste).
    let resid_f = bin_residual as f64;
    if resid_f < mean_residual {
        score += 0.15 * (mean_residual - resid_f);
    } else {
        score -= 0.05 * (resid_f - mean_residual);
    }

    // Progress-aware tightness: early in stream, prefer keeping residuals
    // flexible (large); late in stream, prefer filling bins tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

