pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins whose residual is consumed almost exactly.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    if fill_ratio > 0.85 {
        score -= 60.0 * (fill_ratio - 0.85) / 0.15;
    }

    // Penalize creating awkward dead space (small leftovers that few items can use).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny slivers are nearly unusable
    } else if post_residual >= 10 && post_residual <= 30 {
        score -= 8.0; // still usable by small items
    }

    // Lookahead coupling: reward bins that leave room for the next item.
    if next_item_size > 0 {
        if post_residual as u32 >= next_item_size {
            let slack = post_residual as f64 - next_item_size as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 10.0; // next item cannot follow here
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Global pressure: when many bins are open, prefer consolidating into existing ones.
    let open_pressure = (open_bins_count as f64) / (1.0 + total_items as f64 / 10.0);
    if bin_residual != bin_capacity {
        score -= 5.0 * open_pressure;
    }

    // Mean-residual steering: placing into a bin below mean residual balances load.
    if bin_residual != bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score += 0.15 * diff;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // (large item, poor fits elsewhere) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = fill_ratio > 0.9 || (fitting_bins_count == 0);
        if poor_fit {
            score -= 20.0 + 40.0 * (1.0 - progress);
        } else {
            score += 45.0 + 30.0 * open_pressure;
        }
    }

    // Time horizon: late in the stream, be extra frugal with new bins.
    score += 10.0 * (step_index as f64 / (total_items.max(1) as f64)) * (post_residual as f64 / bin_capacity as f64);

    score
}

