    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let pr = post_residual as f64;
    let pr_norm = pr / bin_capacity as f64;
    let w = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += w * pr_norm * pr_norm * 40.0; // penalize large leftover waste later in stream

    // Reward tight fits (small post_residual) with a quadratic bonus.
    score -= (1.0 - pr_norm) * (1.0 - pr_norm) * 12.0;

    // Last-chance bin bonus: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    } else if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64 - 2.0).min(5.0);
    }

    // Next-item lookahead: if the next item fits exactly in post_residual, reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 10.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > post_residual {
        score += 4.0;
    }

    // Coupling with mean residual: bins far below mean residual are more valuable targets.
    score -= 0.15 * (mean_residual - bin_residual as f64);

    // Mild penalty for opening new bins early when alternatives exist.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 18.0 - 14.0 * progress;
    }

