        if gap > 0.0 && gap < 12.0 {
            score += 2.2 * (12.0 - gap);
        }
    }

    // Compare against mean residual: bins with residual close to item size are attractive.
    let diff = (bin_residual as f64 - item_size as f64 - mean_residual).abs();
    score += 0.25 * diff;

    // Last chance: strongly favor using this bin before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // When many bins can fit the item, prefer the tightest (smallest leftover).
    if fitting_bins_count > 2 {
        score += 0.4 * (bin_residual - item_size) as f64;
    }

    // Early stream: prefer keeping large residual bins flexible.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.4 {
        score += 0.25 * post_residual as f64;
    } else if progress > 0.85 {
        // Endgame: waste-averse — push hard toward tight fits.
        score += 0.5 * post_residual as f64;
    } else {
        score += 0.1 * post_residual as f64;
    }

    // Late stream with many open bins: reward bins already mostly full.
    if progress > 0.7 && open_bins_count > 4 {
        let fill = 1.0 - bin_residual as f64 / bin_capacity as f64;
        score -= 30.0 * fill;
    }

    // Reward near-exact fills relative to capacity scale.
    let fill_ratio = 1.0 - (bin_residual.saturating_sub(item_size)) as f64 / bin_capacity as f64;
    if fill_ratio > 0.9 {
        score -= 15.0 * (fill_ratio - 0.9) * 10.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        score += 20.0;
        if fitting_bins_count == 0 {
            score -= 600.0;
        } else if item_size > bin_capacity / 2 && fitting_bins_count <= 2 {
            // Large item with few options: a fresh bin keeps small residuals usable.
            score -= 80.0;
        } else {
            let waste = (bin_residual - item_size) as f64;
            let nxt = next_item_size.max(1) as f64;
            if waste > 0.0 && waste < nxt {
                // The waste in open bins is smaller than the next item —
                // it's recoverable, so opening a new bin is wasteful.
                score -= 120.0 * (1.0 - waste / nxt);
            } else if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
                score += 30.0 + 0.3 * post_residual as f64;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" the leftover is
    // modulo common item-size classes (1..=100 stream, so use finer classes).
    let pr = post_residual;
    let cap = bin_capacity as f64;

    // Class A: post_residual exactly divisible by common small sizes -> highly reusable.
    for divisor in [10u32, 20, 25, 50].iter() {
        if pr > 0 && pr % divisor == 0 {
            score -= 6.0;
        }
    }

    // Class B: post_residual in a "dead zone" (1..=9 or exact awkward leftovers)
    if pr < 10 && pr > 0 {
        score += 12.0; // unusable dead space
    }

    // Harmonic coupling: does next_item_size divide or nearly fit post_residual?
    if next_item_size > 0 && next_item_size <= pr {
        let gap = pr - next_item_size;
        if gap == 0 {
            score -= 15.0; // perfect harmonic match with lookahead
        } else if gap % 10 == 0 {
            score -= 8.0;
        } else {
            score -= 3.0;
        }
    } else if next_item_size > 0 && next_item_size > pr {
        // lookahead item can't use this residual: penalize proportionally
        score += (next_item_size - pr) as f64 * 0.15;
    }

    // Capacity-fraction classes: reward residuals that are clean fractions of capacity
    let frac = pr as f64 / cap;
    if (frac * 4.0).round() as i32 * 25 == pr as i32 {
        score -= 4.0; // residual is 0%, 25%, 50%, 75%, 100% of capacity
    }

    // Integer-division threshold on post_residual: buckets of 33/34
    let bucket = pr / 34;
    score -= bucket as f64 * 2.0; // bigger usable buckets preferred

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize mildly so it's chosen only when open bins are bad
    if bin_residual == bin_capacity {
        score += 5.0 + mean_residual * 0.05;
    }

    // Late-stream consolidation: prefer tightening bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_residual - post_residual) as f64 * 0.1;

    // Prefer bins tighter than the mean residual (good fits)
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever hold
    // the smallest plausible item (<= ~9) are pure waste. Penalize hard.
    if post_residual > 0 && post_residual <= 9 {
        score += 40.0 + (10 - post_residual as f64) * 8.0; // smaller gap = worse
    }
    // Mid-range gaps (10..=19) are only usable by small items: mild penalty.
    if post_residual >= 10 && post_residual <= 19 {
        score += 6.0;
    }

    // Perfect or near-perfect fits are highly desirable.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Reward bins whose residual was large relative to mean (tight packing targets).
    if (bin_residual as f64) > mean_residual + 5.0 {
        score -= 3.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack <= 5.0 {
            score -= 15.0;
        } else {
            score -= 4.0;
        }
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing bins
    // rather than opening new ones; also slightly prefer bins below mean residual
    // (fill the emptier ones last? no: fill fullest first to close them).
    let pressure = (open_bins_count as f64).ln().max(1.0);
    score += pressure * 1.5;

    // New-bin candidate: opening a new bin is only attractive when no open bin
    // gives a good fit (post_residual here equals capacity - item_size).
    if bin_residual == bin_capacity {
        let waste = post_residual as f64;
        // Base cost of a new bin, discounted if item is large (hard to place later).
        score = 25.0 + waste * 0.5 - (item_size as f64) * 0.15;
        // If many bins are open and item is small, new bin is wasteful.
        if item_size < 40 && open_bins_count > 2 {
            score += 10.0;
        }
        // Late in the stream, prefer closing out existing bins.
        if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.8 {
            score += 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: reward bins whose post-residual matches the next item exactly.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        score -= 12.0 * (1.0 - gap / (bin_capacity as f64 + 1.0)).max(0.0);
        // Perfect two-item fill bonus
        if post_residual as i64 == next_item_size as i64 {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // next item fits in the resulting gap: mild bonus scaled by tightness
            score -= 6.0 * (next_item_size as f64 / (post_residual as f64 + 1.0));
        } else {
            // next item won't fit: penalize leftover dead space more
            score += 4.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    } else {
        // Last item: pure tightness
        score -= 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Prefer tight fits relative to current bin residual
    score += 2.0 * (post_residual as f64 / bin_residual as f64);

    // Relative to mean residual: bins with below-mean residual are "hot", prefer using them
    score += 1.5 * (post_residual as f64 - mean_residual) / (bin_capacity as f64);

    // Last-chance bin: strongly favor it to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // Late in stream: be more conservative, avoid fragmenting bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Slight penalty for many open bins (encourage consolidation)
    score += 0.3 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

