pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual)
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small for typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: reward bins whose post residual can still host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 4.0;
        }
        // Perfect chain fit: post residual exactly matches next item
        if post_residual == next_item_size {
            score -= 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize unless item is large or current bins are crowded
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = mean_residual / bin_capacity as f64;
        let large_item = item_size > 60;
        if large_item || crowding < 0.15 || (next_item_size > 0 && next_item_size + item_size > bin_capacity) {
            score -= 5.0 * progress;
        } else {
            score += 10.0;
        }
