    let fill = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 3.0 * fill * (step_index as f64 / (total_items.max(1) as f64));

    // Penalize bins far from mean residual (prefer balanced residual distribution)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Smooth polynomial coupling: reward small post-residual more strongly as stream progresses.
    let tightness = 1.0 - norm_pr;
    let coupling = (1.0 + 3.0 * progress) * tightness * tightness * cap * 0.35;
    score -= coupling;

    // Penalize dead space: cubic penalty on normalized post-residual, amplified by mean residual gap.
    let dead = norm_pr * norm_pr * norm_pr * cap * 0.6;
    score += dead * (1.0 + (mean_residual / cap).max(0.0));

    // Lookahead: reward if next item fits into post-residual (smooth affinity).
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if ns <= pr {
            let slack = (pr - ns) / cap;
            score -= (1.0 - slack) * (ns / cap) * 25.0 * (1.0 + progress);
        } else {
            // penalize leaving a gap just below next item size
            let gap = (ns - pr) / cap;
            score += gap * gap * 20.0;
        }
    } else {
        // last item: strongly prefer tightest fit
        score -= (cap - pr) * 0.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0 * (1.0 - norm_pr);
    }

    // Mild penalty for spreading across many open bins when residual is large.
    score += (open_bins_count as f64).ln().max(0.0) * norm_pr * 4.0;

    // New-bin candidate handling: make fresh bin attractive only when open bins are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap - 0.5).max(0.0);
        score = cap * (0.9 - 0.5 * fragmentation) + (fitting_bins_count as f64) * 2.0;
        if next_item_size > 0 && (next_item_size as f64) <= cap * 0.5 {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

