    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Integer-division thresholds: classify post_residual into capacity fractions
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let sixteenth = bin_capacity / 16;

    // Dead-space penalty grows super-linearly when post_residual falls into
    // "unusable" harmonic classes (too small for typical items).
    if post_residual > 0 && post_residual < sixteenth {
        score += 60.0; // tiny sliver: nearly dead space
    } else if post_residual < eighth {
        score += 20.0;
    }

    // Reward exact harmonic fills: post_residual that is a clean fraction of capacity
    let mod16 = post_residual % 16;
    if mod16 == 0 {
        score -= 8.0;
    } else {
        score += (mod16 as f64) * 0.5;
    }

    // Modulo coupling with next item: if next item exactly fits post_residual,
    // strongly reward (perfect harmonic closure).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size < post_residual {
            let nxt_res = post_residual - next_item_size;
            // penalize based on how "off-harmonic" the resulting residual is
            score += ((nxt_res % 8) as f64) * 1.5;
            if nxt_res < eighth && nxt_res > 0 {
                score += 15.0;
            }
        } else {
            // next item cannot follow into this bin: penalize mildly
            score += 6.0;
        }
    }

    // Fraction-of-capacity coupling: prefer bins whose fill level lands on
    // coarse capacity fractions (1/2, 3/4 full) after placement.
    let fill = (bin_capacity - post_residual) as f64 / cap;
    let fill_class = (fill * 4.0).floor(); // quarters of the bin
    score -= fill_class * 2.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: neutral-ish baseline; open only if all open bins are bad
    if bin_residual == bin_capacity {
        score = 0.35 * cap + 0.2 * mean_residual - 10.0 * (fitting_bins_count as f64);
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // new bin guarantees perfect fit for next item too
            score -= 5.0;
        }
    }

    // Stream progression: later in stream, be greedier about tight fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (post_residual as f64) * 0.3;

    // Mean residual coupling: if this bin is far below mean residual, it's a
    // good "garbage collector" bin; reward using it.
    let dev = mean_residual - (bin_residual as f64);
    if dev > 0.0 {
        score -= dev * 0.4;
    }

    score
}

