    score -= 30.0 * fill * fill;

    // Open bins pressure: penalize using bins when many are open,
    // unless this is the only fitting bin (last-chance placement).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0; // last chance: strongly favor this bin
