pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);

    // Smooth non-linear coupling: post_residual weighted by progress-dependent factor
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap; // normalized post residual in [0,1]

    // Polynomial in progress: penalize large residuals more as stream progresses
    let progress_weight = 0.5 + 1.5 * progress * progress; // quadratic in progress
    score += progress_weight * 30.0 * norm_pr * norm_pr;

    // Dead-space penalty: small post_residual that can't hold typical next item
    let nxt = next_item_size as f64;
    if nxt > 0.0 {
        let waste = (nxt - pr).max(0.0) / cap;
        score += 40.0 * waste * waste; // quadratic waste penalty
        // Reward bins where next item also fits smoothly (smooth coupling)
        let fit_next = (pr - nxt).max(0.0) / cap;
        score -= 15.0 * fit_next * (1.0 - fit_next) * 4.0; // concave reward, peaks at moderate slack
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - norm_pr) * (1.0 - norm_pr);
    }

    // Interaction: tight fits (small post_residual) rewarded via smooth term
    score -= 20.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 + progress);

    // Mild penalty for spreading across too many open bins early
    let bins_norm = open_bins_count as f64 / (total_items.max(1) as f64).sqrt();
    score += 3.0 * bins_norm * progress;

    // Smooth interaction with mean residual: prefer bins below mean residual (tighter)
    let mean_norm = mean_residual / cap;
    let diff = norm_pr - mean_norm;
    score += 8.0 * diff * diff - 10.0 * diff; // convex bowl centered slightly below mean

    // New-bin candidate: penalize opening a fresh bin unless residual is unusable
    if bin_residual == bin_capacity {
        let unusable = ((pr) as f64 / cap).max(0.0);
        score += 10.0 + 25.0 * (1.0 - progress) * (1.0 - unusable);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space value depends on which
    // capacity fraction band it falls into. Small residuals are "dead space"
    // (penalize less only if truly tiny), mid residuals are the worst waste.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit is ideal
    } else if pr <= 5 {
        score -= 25.0; // near-perfect, almost dead anyway
    } else if pr <= 10 {
        score += 5.0; // awkward small gap, hard to refill
    } else if pr <= 20 {
        score += 15.0; // worst band: too small for most items
    } else if pr <= 30 {
        score += 5.0;
    } else if pr <= 50 {
        score -= 10.0; // half-bin class, refillable
    } else {
        score -= 5.0; // large residual, flexible
    }

    // Integer-division class: residual mod 10 as a harmonic sub-class.
    // Multiples of 10 align with typical item granularity.
    if pr % 10 == 0 && pr > 0 {
        score -= 6.0;
    }

    // Lookahead: reward if next item fits exactly in post_residual.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot use this bin's post space: penalize large waste
            score += 8.0;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a bin should only win when the
    // current bin would leave a very awkward residual, or when bin pressure
    // is low relative to stream progression.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let awkward = (pr > 10 && pr <= 25) as i32 as f64;
        // Base cost of a fresh bin, discounted late in the stream.
        score = 40.0 - 15.0 * progress + 10.0 * awkward;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            // next item could go in the fresh space too; slight bonus
            score -= 5.0;
        }
        if mean_residual > 40.0 && open_bins_count > 2 {
            score += 10.0; // plenty of room elsewhere; avoid bin proliferation
        }
    }

    // Mild preference for tighter bins among equals.
    score += 0.05 * (bin_residual as f64 - post_residual as f64).recip().max(0.0);

    score
}

