    // Open-bin pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 20.0 + 3.0 * open_bins_count as f64;
        // But allow a new bin if the fit in existing bins would be terrible
        // (post_residual small but nonzero) and lookahead item needs space.
        if post_residual > 0 && post_residual < 10 {
