        score += (bin_residual as f64 - mean_residual).abs() * 0.05;
    }

    // Lookahead coupling: if next item fits exactly in the post-residual, reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }
    // Penalize if post_residual is too small for the next item (dead space for lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 4.0;
    }

    // Mild late-stream pressure to close bins tightly.
    let progress = step_index as f64 / total_items as f64;
    score += post_residual as f64 * 0.1 * progress;

