    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when decent fits exist, unless item is huge and stream is early
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let open_penalty = 40.0 * (1.0 - progress);
        let item_pressure = (item_size as f64 / bin_capacity as f64).powi(2) * 30.0;
        score += open_penalty - item_pressure;
