pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0; // dead space zone 1..9
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward residual exactly matching the next item's size (chain fit).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    // Penalize leaving a gap that cannot hold the next item but is too small to be useful.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 20.0;
    }

    // Open-bin pressure: discourage scattering across many bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New empty bin candidate: penalize unless current bin residuals are badly fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        score += 40.0 - 60.0 * fragmentation;
        // Late in the stream, opening fresh bins is cheaper than dead space.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * progress;
    }

    // Mild alignment with mean residual: prefer bins below average residual (tighter bins).
    score += (mean_residual - bin_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: strongly reward exact match of post_residual with next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        if diff == 0 {
            score -= 60.0; // perfect chain fit
        } else {
            // penalize leaving a gap that the next item cannot use well
            score += (diff as f64) * 0.9;
            // if next item won't fit at all here, small penalty
            if post_residual < next_item_size {
                score += 8.0;
            }
        }
    } else {
        // last item: prefer minimal waste
        score += 0.0;
    }

    // Prefer bins with residual close to the mean (keep residuals uniform)
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.25;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize creating tiny unusable dead space (dead space < 10 cannot fit any item)
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Mildly discourage opening new bins when many bins are already open
    if bin_residual == bin_capacity {
        score += open_bins_count as f64 * 1.5;
        // but if lookahead item is large and no good fit exists, new bin is fine
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 10.0;
        }
    }

    // Slight progression term: later in the stream, consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) via non-linear shaping.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * fit_ratio * 40.0;

    // Penalize leaving dead space that cannot fit the next item's lookahead.
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            // dead space: cannot host the next item
            score += (next_item_size - post_residual) as f64 * 0.6;
        } else if post_residual >= next_item_size {
            // bonus: bin remains useful for the lookahead item
            score -= 4.0 + 0.25 * next_item_size as f64;
        }
    } else {
        // Last item: just fill as much as possible
        score -= item_size as f64 * 0.3;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate logic: only attractive when the item fits poorly everywhere
    // or open bins are very full on average.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_fullness = 1.0 - mean_residual / bin_capacity as f64;
        // New bin gets a base penalty; reduced when open bins are congested.
        let mut new_bin_score = 55.0
            - 35.0 * avg_fullness
            - 10.0 * progress
            - 0.5 * open_bins_count as f64;
        // If item is large, a fresh bin is more acceptable.
        new_bin_score -= item_size as f64 * 0.15;
        // If no other bin fits, new bin is fine.
        if fitting_bins_count == 0 {
            new_bin_score -= 40.0;
        }
        score += new_bin_score;
    } else {
        // Reward using bins whose residual is close to the item (best-fit flavor).
        let tightness = 1.0 - (bin_residual - item_size) as f64 / bin_capacity as f64;
        score -= tightness * 12.0;

        // Mildly prefer bins with residual near mean (avoid fragmenting outliers).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.08;
    }

    // Late-stream pressure: consolidate more aggressively as the stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 6.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let mut score = pr;

    // Smoothly increasing weight on tight fits as the stream progresses.
    let progress_weight = 0.6 + 1.4 * progress * progress;
    score += progress_weight * norm_pr * norm_pr * cap;

    // Reward small post-residual with a smooth cubic decay term.
    score -= (1.0 - norm_pr).powi(3) * (item_size as f64) * (0.4 + 0.6 * progress);

    // Penalize dead space relative to mean residual smoothly.
    let dev = pr - mean_residual;
    score += 0.25 * dev * dev / cap;

    // Lookahead coupling: smooth reward if next item fits post-residual.
    if next_item_size > 0 {
        let fits = (next_item_size as f64) <= pr;
        let margin = pr - next_item_size as f64;
        let bonus = if fits { (1.0 - margin / cap).abs() } else { -1.0 };
        score -= 8.0 * bonus * (0.5 + progress);
    }

    // Last-chance bin: smooth urgency term.
    if fitting_bins_count == 1 {
        score -= 15.0 * (0.3 + 0.7 * progress);
    }

    // Mild penalty for many open bins, smoothed.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    // New-bin candidate: prefer it only when residual is large and stream early.
    if bin_residual == bin_capacity {
        let openness = (1.0 - progress).max(0.0);
        score -= 12.0 * openness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residuals divisible by common item sizes
    // (or zero) are "good" classes; odd awkward residuals are dead space.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect closure
    } else {
        // class score: how "harmonic" the residual is w.r.t. small item sizes
        let mut harm = 0.0f64;
        for d in [10u32, 20, 25, 50].iter() {
            if pr % d == 0 { harm += 8.0; }
        }
        if pr < 10 { harm -= 25.0; } // tiny dead space is nearly unusable
        score -= harm;
    }

    // Lookahead: does next item fit exactly / well in the post residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            let slack = pr - next_item_size;
            score -= 15.0 - 0.3 * slack as f64;
        } else {
            // next item won't fit here; residual likely becomes dead space
            score += 0.15 * (next_item_size - pr) as f64;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current bin fit is poor
    if bin_residual == bin_capacity {
        // penalize opening a new bin unless item is large and fit is bad
        let poor_fit = post_residual as f64 > 0.5 * bin_capacity as f64 && post_residual > 0;
        score += if poor_fit { 0.0 } else { 45.0 };
        if item_size >= 60 { score -= 20.0; }
    }

    // Tight fit reward relative to item size
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness;

    // Stream progression: late in stream, be more conservative with new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity { score += 10.0 * progress; }

    // Prefer fuller bins when many bins are open
    score -= 0.05 * open_bins_count as f64 * (bin_residual as f64 / bin_capacity as f64);

    score += 0.05 * (mean_residual - post_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no plausible item (1..=100)
    // can use well are penalized. A gap of 0 is perfect; a gap too small to
    // hold even a modest item is a "dead zone" and gets a steep penalty.
    if post_residual > 0 {
        let gap = post_residual as f64;
        // Items are 1..=100, unknown distribution: assume typical items >= 10-ish.
        // Gaps below ~15 are nearly unusable; gaps >= 50 are still flexible.
        if gap < 15.0 {
            score += 60.0 * (15.0 - gap) / 15.0; // dead-space wall
        } else if gap < 30.0 {
            score += 20.0 * (30.0 - gap) / 15.0; // awkward zone
        } else {
            // Mild penalty proportional to wasted capacity, softened for large gaps
            score += 0.15 * gap;
        }
    }

    // Exact fit bonus
    if post_residual == 0 {
        score -= 100.0;
    }

    // Open-bin pressure: discourage spreading across many bins when
    // open_bins_count is high; encourage consolidating into existing bins.
    let pressure = open_bins_count as f64;
    score += 0.8 * pressure;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: an empty bin is a fresh resource. Only prefer
    // it when the item would leave an awkward gap in every open bin, or when
    // bin pressure is low enough that a clean bin is worth it.
    if bin_residual == bin_capacity {
        // Neutral-ish base for a new bin; the dead-space penalty on the item's
        // post_residual (bin_capacity - item_size) already applies above.
        // Add a fixed opening cost so we don't open bins frivolously.
        score += 30.0;
        // If many bins are open, opening another is costly.
        score += 1.5 * pressure;
        // But if the item is large, a fresh bin is often the cleanest fit.
        if item_size >= 60 {
            score -= 55.0;
        }
    }

    // Lookahead: if the next item fits the post_residual well, reward this placement.
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if post_residual as f64 >= ns && (post_residual as f64 - ns) < 15.0 {
            score -= 25.0; // chains a good future fit
        } else if ns > post_residual as f64 && ns <= bin_residual as f64 {
            // next item needs more than post_residual but fits the bin now:
            // placing current item here may block it; mild penalty
            score += 10.0;
        }
    }

    // Slight preference for filling fuller bins overall (best-fit flavor)
    score -= 0.3 * (bin_capacity - bin_residual) as f64;

