    if fill_ratio > 0.9 {
        score -= 15.0 * (fill_ratio - 0.9) * 10.0;
    }

    // New empty bin decision
    if bin_residual == bin_capacity {
        score += 20.0;
        score -= 20.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 600.0;
        } else if item_size > bin_capacity / 2 && fitting_bins_count <= 2 {
            score -= 80.0;
        } else {
            let waste = (bin_residual - item_size) as f64;
            let nxt = next_item_size.max(1) as f64;
            if waste > 0.0 && waste < nxt {
                score -= 120.0 * (1.0 - waste / nxt);
            } else if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
                score += 30.0 + 0.3 * post_residual as f64;
            }
        }
    }

    // Late stream: prefer filling existing bins deeply
    if progress > 0.7 && open_bins_count > 4 {
        let fill = 1.0 - bin_residual as f64 / bin_capacity as f64;
        score -= 30.0 * fill;
    }

    // Early stream: mild preference for compacting into tighter bins
    if progress < 0.4 && fitting_bins_count > 2 {
        score += 0.25 * (bin_residual - item_size) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post-residual exactly
    // or closely matches the next item size (it can be consumed immediately).
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (post_residual as f64 - next).abs() < 1.0 {
            // Perfect match: next item fills this bin exactly.
            score -= 60.0;
        } else if post_residual >= next_item_size {
            let slack_after_next = post_residual as f64 - next;
            // Reward tight fit of the next item; penalize leftover dead space.
            score -= 40.0 - slack_after_next.min(40.0);
        } else {
            // Next item won't fit here: penalize proportionally to the gap.
            let gap = next - post_residual as f64;
            score += gap.min(60.0);
        }
    }

    // Compare post-residual against the mean residual of open bins.
    // Leaving a bin far below mean residual wastes capacity elsewhere.
    let mean_gap = mean_residual - post_residual as f64;
    if mean_gap > 0.0 {
        score += mean_gap * 0.3;
    } else {
        score += mean_gap * 0.15; // slight reward for staying above mean
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Perfect fill now.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Late in the stream, prefer closing bins tightly (reduce fragmentation).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * (0.5 + 0.5 * progress);

    // New-bin candidate: only attractive when current bins are very tight.
    if bin_residual == bin_capacity {
        let avg_tightness = 1.0 - (mean_residual / bin_capacity as f64);
        score += 45.0 * avg_tightness - 10.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0; // fresh bin accommodates lookahead well
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Primary: reward tight fits (small post_residual) with a convex penalty.
    let frac = post_residual as f64 / bin_capacity as f64;
    score += frac * frac * 40.0;

    // Lookahead: if the next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; penalize leaving medium dead space.
        if post_residual < 10 {
            score -= 5.0; // tiny dead space is fine
        } else if post_residual < 30 {
            score += 10.0; // medium dead space is waste
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Crowding control: with many open bins, favor filling existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (open_bins_count as f64).ln().max(0.0) * 3.0;

    // Compare against mean residual: bins with residual near mean are neutral,
    // outliers (very full or very empty) get gentle shaping.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05 * progress;

    // Late in the stream, be more aggressive about closing bins tightly.
    score -= progress * 6.0 * (1.0 - frac);

    // New-bin candidate: only attractive when current bin would leave a bad
    // residual (too small for typical items) or no bin fits well.
    if bin_residual == bin_capacity {
        let bad_fit = post_residual == 0
            || (post_residual > 0 && post_residual < 15);
        if bad_fit || fitting_bins_count == 0 {
            score -= 12.0;
        } else {
            score += 20.0 + 0.3 * open_bins_count as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let cap = bin_capacity as f64;

    // Base: prefer minimal post residual (tight fit)
    let mut score = pr;

    // Smooth non-linear coupling of post_residual with stream progress:
    // late in the stream, small residuals matter more (dead space cost rises)
    let pr_norm = pr / cap;
    score += 20.0 * pr_norm.powi(3) * (0.5 + progress);

    // Reward tight fits: quadratic fit-quality term
    let fit_quality = it / bin_residual.max(1) as f64;
    score -= 15.0 * fit_quality * fit_quality;

    // Last-chance bin: strong reward to use it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly in post_residual, reward strongly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack = (pr - nxt) / cap;
            score -= 12.0 * (1.0 - slack) * (1.0 - slack);
        } else {
            // penalize blocking the next item
            score += 8.0 * (nxt - pr) / cap;
        }
    }

    // Prefer filling bins that are already below mean residual (balance residuals)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 6.0 * dev * dev.abs();

    // Late-stream: slightly discourage opening many new bins
    if bin_residual == bin_capacity {
        score += 5.0 * (1.0 - progress) + 3.0 * (open_bins_count as f64).ln().max(0.0) * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into residue classes mod 10 (dead-space granularity)
    let post = post_residual as i64;
    let residue_class = post % 10;

    // Dead space penalty grows super-linearly for unusable small remainders (<10, since items >= 1... but classes help)
    if post > 0 && post < 10 {
        score += (10 - post) as f64 * 3.0; // tiny dead space is very bad
    }

    // Harmonic reward: post_residual exactly divisible by common item-size classes (10,20,25,50)
    if post > 0 {
        if post % 50 == 0 { score -= 12.0; }
        else if post % 25 == 0 { score -= 8.0; }
        else if post % 20 == 0 { score -= 6.0; }
        else if post % 10 == 0 { score -= 4.0; }
        else {
            // penalize awkward residues proportionally to distance from nearest multiple of 10
            let dist = residue_class.min(10 - residue_class) as f64;
            score += dist * 0.8;
        }
    }

    // Perfect fit is best
    if post == 0 {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual > next_item_size {
            let next_post = post_residual - next_item_size;
            if next_post % 10 == 0 || next_post == 0 { score -= 5.0; }
            if next_post < 10 && next_post > 0 { score += 4.0; } // creates tiny dead space after next
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Prefer fuller bins when many bins are open (consolidation pressure)
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 6.0;

    // Mild penalty for spreading across many bins when mean residual is high
    if open_bins_count > 2 && mean_residual > 30.0 {
        score += 2.0;
    }

    // Slight preference for existing bins over opening new ones (new bin candidate has full residual => high base score already)
    if bin_residual == bin_capacity {
        score += 5.0; // opening a new bin costs a bit unless fit is clearly better
    }

    // Stream progression: later in stream, be more conservative (favor tight packing)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual <= 20 {
        score -= 6.0; // gaps that can still hold small items are good
    } else if post_residual == 0 {
        score -= 12.0; // perfect fit
    }

    // Large dead space is mildly wasteful too.
    if post_residual > 40 {
        score += (post_residual as f64 - 40.0) * 0.15;
    }

    // Open-bin pressure: discourage spreading when many bins are open.
    score += (open_bins_count as f64) * 0.4;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: reward leaving a gap that fits the next item exactly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0;
        if post_residual == next_item_size {
            score -= 6.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 5.0; // dead space relative to the known future demand
    }

    // New-bin candidate: make it slightly unattractive unless residuals are bad.
    if bin_residual == bin_capacity {
        score += 8.0 + mean_residual * 0.05;
    }

    // Late in the stream, tighten packing (less room to recover).
    let progress = step_index as f64 / total_items as f64;
    score += post_residual as f64 * progress * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer perfect fits.
    if post_residual == 0 {
        score -= 200.0;
    } else {
        // Penalize dead space that is too small to be useful later.
        let dead = post_residual as f64;
        if dead < 10.0 {
            score += 3.0 * (10.0 - dead);
        }
    }

    // 2-step lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Exact chain fit is best.
            if post_residual == next_item_size {
                score -= 120.0;
            } else {
                // Reward but penalize leftover slack after chaining.
                let chain_slack = (post_residual - next_item_size) as f64;
                score -= 60.0 - 0.4 * chain_slack;
            }
        } else {
            // Next item cannot follow here; penalize proportionally to waste.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap;
        }
    }

    // Compare against mean residual: bins tighter than average are better targets.
    score += 0.3 * (mean_residual - bin_residual as f64).abs().copysign(1.0) * if (bin_residual as f64) < mean_residual { -1.0 } else { 1.0 };

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: make it unattractive unless nothing fits well.
    if bin_residual == bin_capacity {
        score += 150.0 + 0.5 * item_size as f64;
        // Late in stream, opening new bins is less costly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 50.0 * progress;
    }

    // Mild preference for fuller bins overall.
    score -= 0.1 * (bin_capacity - bin_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: fraction of bin consumed by this item.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 40.0 * fill * fill;

    // Penalize dead space that is too small to be useful later.
    // Residuals below the minimum plausible item size are pure waste.
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual <= 20 {
        score += 8.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // this placement is excellent; if it just barely doesn't fit,
    // this placement may block the next item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let next_fit = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - next_fit / bin_capacity as f64);
        } else {
            let miss = (next_item_size - post_residual) as f64;
            score += 10.0 * (miss / bin_capacity as f64);
        }
    }

    // Last-chance bonus: this is the only bin that can take the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Prefer using existing crowded bins over leaving many half-empty bins.
    let crowding = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 15.0 * crowding;

    // Global pressure: many open bins -> favor filling existing ones
    // (penalize new-bin candidate via its perfect residual).
    let pressure = open_bins_count as f64 / (total_items.max(1) as f64).sqrt().max(1.0);
    score += pressure * (bin_residual as f64 / bin_capacity as f64) * 10.0;

    // Time horizon: early in the stream, keep bins flexible (avoid tiny residuals);
    // late in the stream, pack aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if progress < 0.3 && post_residual > 0 {
        score += (post_residual as f64 / bin_capacity as f64) * 5.0;
    } else if progress > 0.7 {
        score -= 6.0 * (bin_residual as f64 / bin_capacity as f64);
    }

    // Compare against mean residual: bins far below mean residual are
    // already tight; prefer placing into bins near or above the mean
    // to balance residual distribution.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev;

    // New-bin candidate: opening a new bin is only attractive when the
    // item is large relative to capacity or the current bin is a bad fit.
    if bin_residual == bin_capacity {
        let openness = 1.0 - fill;
        score += 35.0 * openness;
        if fitting_bins_count > 0 {
            score += 20.0; // discourage opening when a fit exists
        }
        if item_size >= 60 {
            score -= 25.0; // big items may warrant fresh bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let mut score = x * (1.0 + 0.8 * progress * progress) + 0.9 * x * x * (1.0 - progress);

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - x;
    score -= 1.5 * tightness * tightness * (0.5 + progress);

    // Penalize dead space relative to mean residual of open bins
    score += 0.3 * (pr - mean_residual).abs() / cap;

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 2.0;
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr >= ns {
            let gap = (pr - ns) / cap;
            score -= 0.6 * (1.0 - gap * gap);
        } else {
            score += 0.8 * (ns - pr) / cap;
        }
    }

    // Mild penalty for too many open bins
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls in "dead zones"
    // (very small residuals that nothing will ever fit into) are penalized.
    let dead_zone = if post_residual < 10 { 1.0 } else { 0.0 };
