    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 0.15 * (1.0 - progress);

    // Deviation from mean residual: prefer bins tighter than average.
    score += (bin_residual as f64 - mean_residual) * 0.2;

    // New-bin candidate: only attractive when current bins are poor fits.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score = (bin_capacity as f64) - pressure * 200.0 - (fitting_bins_count as f64) * 30.0;
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 100.0;
        }
    }

    score
