            score -= 300.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item does NOT fit in the leftover: penalize dead space
            score += 0.5 * gap;
        }

        // Coupling with mean residual: prefer bins whose leftover is close to
        // what the stream "typically" leaves, when chain is not exact
        score += 0.2 * (post_residual as f64 - mean_residual).abs();
    }

    // Last-chance bin before opening a new bin: strong reward to use it
    if fitting_bins_count == 1 {
        score -= 250.0;
    }

    // New-bin candidate: make it attractive only when nothing fits well
    if bin_residual == bin_capacity {
        // base cost of opening a bin
        score += 120.0;
        // if lookahead item is large, opening fresh is more attractive
        if next_item_size > 0 {
            score -= (next_item_size as f64) * 0.6;
        }
        // late in the stream, avoid opening new bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 150.0 * progress;
    }

    // Mild penalty for very small unusable leftovers (dead space)
    if post_residual > 0 && post_residual < 10 {
