pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity)
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 40.0;

    // Reward perfect fits heavily
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Penalize dead space that is too small for typical items (unusable gap)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a new bin should only win when
    // no open bin offers a decent fit. Base penalty grows with stream progress
    // (later in the stream, waste is harder to amortize) and with open bin count.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_score = 55.0 + 25.0 * progress + 2.0 * open_bins_count as f64;

        // If the next item is large and this bin would be nearly empty after,
        // a fresh bin may be strategically useful — soften the penalty.
        if next_item_size > 0 && next_item_size as f64 >= 0.6 * bin_capacity as f64 && post_residual as f64 >= 0.9 * bin_capacity as f64 {
            new_bin_score -= 30.0;
        }
        // If mean residual across open bins is high, open bins are fragmented;
        // a new bin is less costly relative to the mess.
        new_bin_score -= (mean_residual / bin_capacity as f64).clamp(0.0, 1.0) * 15.0;

        score = new_bin_score;
    }

    // Lookahead synergy: if the next item fits exactly in the post residual,
    // reward this placement (chains two good fits).
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual - next_item_size < 10 {
            score -= 10.0;
        }
    }

    // Mild penalty when placing into a bin whose residual is far above the
    // mean (keeps large residuals available for large future items).
    if bin_residual != bin_capacity {
        let dev = bin_residual as f64 - mean_residual;
        if dev > 0.0 {
            score += dev * 0.15;
        }
    }

    // Early stream: be slightly conservative about fragmenting bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if progress < 0.2 && post_residual > 0 && post_residual < 20 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Exact fill: perfect compaction, strong reward
    if post_residual == 0 {
        score -= 1200.0;
    }

    // Lookahead: post-residual fits next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let tightness = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 60.0 + 130.0 * tightness;
        // Perfect lookahead match bonus
        if post_residual == next_item_size {
            score -= 55.0;
        }
        let two_step = post_residual.saturating_sub(next_item_size);
        if two_step >= item_size.min(next_item_size) {
            score -= 25.0;
        } else {
            score += 15.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Residual too small for next item: dead space for lookahead
        score += 1.5 * (next_item_size - post_residual) as f64;
    }

    // Small unusable dead bands
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual > 0 && post_residual < 20 {
        score += 12.0 * (1.0 - progress * 0.5);
    }

    // Penalize residuals just barely above next item size (awkward slivers)
    if next_item_size > 0 && post_residual > 0 {
        let gap = post_residual.saturating_sub(next_item_size) as f64;
        if gap > 0.0 && gap < 14.0 {
            score += 2.6 * (14.0 - gap);
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Deviation from mean residual
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.2 * dev;

    // Phase-dependent residual weighting
    if progress < 0.4 {
        score += 0.25 * post_residual as f64;
    } else if progress > 0.85 {
        score += 0.5 * post_residual as f64;
    }

    // New empty bin decision
    if bin_residual == bin_capacity {
        score += 20.0;
        if fitting_bins_count == 0 {
            score -= 600.0;
        } else if item_size > bin_capacity / 2 && fitting_bins_count <= 2 {
            score -= 80.0;
        } else {
            let waste = (bin_residual - item_size) as f64;
            let nxt = next_item_size.max(1) as f64;
            if waste > 0.0 && waste < nxt {
                score -= 120.0 * (1.0 - waste / nxt);
            } else if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
                score += 30.0 + 0.3 * post_residual as f64;
            }
            // Discourage new bin when item is small or waste exceeds next item
            if item_size <= bin_capacity / 4 {
                score += 45.0;
            } else if waste > nxt {
                score += 25.0;
            }
        }
        // Early stream: new bin may pay off later
        score -= 20.0 * (1.0 - progress);
    }

    // Dead-space shaping by fraction of capacity
    let dead = post_residual as f64 / bin_capacity as f64;
    if dead > 0.0 {
        let ideal = if next_item_size > 0 { next_item_size as f64 / bin_capacity as f64 } else { 0.0 };
        if dead < 0.35 {
            score += 90.0 * (0.35 - dead);
        } else if dead < 0.6 {
            let target = ideal.clamp(0.35, 0.6);
            score += 25.0 + 60.0 * (dead - target).abs();
        } else if dead < 0.85 {
