        }
    }

    // Near-exact fills relative to capacity
    let fill_ratio = 1.0 - (bin_residual.saturating_sub(item_size)) as f64 / bin_capacity as f64;
    if fill_ratio > 0.9 {
        score -= 15.0 * (fill_ratio - 0.9) * 10.0;
    }

    // Late-stream compaction: favor tightest bins
    if progress > 0.7 && open_bins_count > 4 {
        let fill = 1.0 - bin_residual as f64 / bin_capacity as f64;
        score -= 30.0 * fill;
    }
    if progress > 0.9 {
        score += 0.8 * post_residual as f64;
    }

    // Multi-bin lookahead: prefer post-residual closest to next item
    if fitting_bins_count > 1 && next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 / (1.0 + slack / 8.0);
    }

    // Early-stream variance control: avoid odd residuals
    if progress < 0.5 && post_residual > 0 && next_item_size > 0 {
        let ratio = post_residual as f64 / next_item_size as f64;
        if ratio > 1.0 && ratio < 1.6 {
            score += 18.0 * (1.6 - ratio);
        }
    }

    score
}

