        let gap = post_residual . saturating_sub (next_item_size) as f64 ;
        if gap > 0.0 && gap < 14.0 { score += 2.6 * (14.0 - gap) ; }
    }
    let fill_ratio = 1.0 - (bin_residual . saturating_sub (item_size)) as f64 / bin_capacity as f64 ;
    if fill_ratio > 0.9 { score -= 15.0 * (fill_ratio - 0.9) * 10.0 ; }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size { score += 1.5 * (next_item_size - post_residual) as f64 ; }
    if progress > 0.9 { score += 0.8 * post_residual as f64 ; }
    if fitting_bins_count == 1 && bin_residual != bin_capacity { score -= 18.0 ; }
    // refined dead-space penalty: penalize residuals just below next item (unusable gap)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 3.0 * (next_item_size - post_residual) as f64 ;
    }
    // reward leaving exactly room for next item plus a small item
    if next_item_size > 0 && post_residual >= next_item_size {
        let rem = post_residual - next_item_size ;
        if rem > 0 && rem <= 10 && fitting_bins_count <= 3 { score -= 12.0 ; }
    }
    // late-stage: strongly prefer tight fits to close bins
    if progress > 0.75 {
        let tight = (bin_residual - item_size) as f64 / bin_capacity as f64 ;
        score += 20.0 * tight ;
    }
    let score = score * 0.95 + diff * 0.05 ;
    let score = score * 0.95 + (1.0 - (bin_residual . saturating_sub (item_size)) as f64 / bin_capacity as f64) * 0.05 ;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: penalize post_residual non-linearly (dead space)
    let mut score = pr * pr / cap;

    // Smooth polynomial coupling with stream progress: prefer tight fits early,
    // tolerate residual slack late (open bins get reused).
    let coupling = pr_norm * (1.0 - pr_norm) * (0.5 + progress);
    score += 40.0 * coupling;

    // Reward filling a bin exactly (post_residual ~ 0)
    score -= (1.0 - pr_norm).powi(3) * 20.0;

    // Last-chance bonus: strongly prefer the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Penalize many open bins mildly to encourage consolidation
    score += (open_bins_count as f64).sqrt() * (1.0 + pr_norm) * 3.0;

    // Lookahead: favor bins whose post residual can host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 10.0 * (nxt / cap);
        } else {
            let gap = (nxt - pr) / cap;
            score += 25.0 * gap * gap;
        }
    }

    // Deviation from mean residual: prefer bins close to mean (balanced packing)
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residual mod capacity fractions.
    // Classify post_residual into harmonic buckets (capacity / k for k=2..5).
    let half = bin_capacity / 2;
    let third = bin_capacity / 3;
    let quarter = bin_capacity / 4;
    let fifth = bin_capacity / 5;

    // Reward placements that leave post_residual in "useful" harmonic classes.
    if post_residual == 0 {
        // Perfect fit: maximal reward.
        score -= 200.0;
    } else if post_residual <= fifth {
        // Tiny dead space: nearly perfect, still excellent.
        score -= 120.0;
    } else if post_residual <= quarter {
        score -= 60.0;
    } else if post_residual <= third {
        score -= 30.0;
    } else if post_residual <= half {
        // Half-capacity leftover is reusable by most items.
        score -= 15.0;
    } else {
        // Large leftover is fine (bin not overly fragmented) — mild bonus.
        score -= 5.0;
    }

    // Modulo arithmetic on post_residual: penalize leftovers that fall into
    // awkward modulo classes relative to common item-size granularities.
    let m10 = post_residual % 10;
    if m10 != 0 {
        score += (m10 as f64) * 0.8; // non-aligned leftovers waste space
    }

    // Integer-division threshold: how many "typical" small items (size ~10)
    // could still fit in the leftover? Reward divisibility headroom.
    let slots = post_residual / 10;
    score -= (slots as f64) * 4.0;

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0;
        if next_item_size == post_residual {
            score -= 60.0; // chained perfect fit
        }
        // Harmonic-class match: next item lands in same residual class
        let next_class = if next_item_size > half { 3 } else if next_item_size > third { 2 } else { 1 };
        let post_class = if post_residual > half { 3 } else if post_residual > third { 2 } else { 1 };
        if next_class == post_class {
            score -= 8.0;
        }
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Next item won't fit here; penalize mildly if this bin was a good
        // candidate otherwise — encourages saving space for the next item.
        score += 6.0;
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: opening a bin should only win when the
    // current bin leaves a truly bad leftover or is nearly full anyway.
    if bin_residual == bin_capacity {
        // Fresh bin baseline: attractive if many bins open and stream is late.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = (bin_capacity as f64) * 0.55 + (open_bins_count as f64) * 3.0 - progress * 20.0;
        // Discourage opening new bins when a decent fit exists elsewhere.
        if fitting_bins_count > 0 && post_residual <= half {
            score += 30.0;
        }
    }

    // Prefer tighter bins (small bin_residual) when leftovers comparable.
    score += (bin_residual as f64) * 0.05;

    // Slight preference for bins below mean residual (consolidation).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..=9) are pure waste.
    if post_residual >= 1 && post_residual < 10 {
        score += 60.0 + (10 - post_residual as i32) as f64 * 4.0;
    }
    // Perfect fit bonus
    if post_residual == 0 {
        score -= 40.0;
    }
    // Reward residuals that can still host typical items; penalize mid-range awkward gaps.
    if post_residual >= 10 && post_residual < 20 {
        score += 6.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, encourage filling.
    score += open_bins_count as f64 * 1.5;

    // New-bin candidate: only attractive when current item fits poorly everywhere.
    if bin_residual == bin_capacity {
        // Prefer new bin if the next item is large and this placement leaves a bad gap.
        if post_residual < 10 || (next_item_size > 0 && next_item_size > post_residual && next_item_size >= 50) {
            score -= 30.0;
        } else {
            score += 20.0 + open_bins_count as f64 * 2.0;
        }
    }

    // Lookahead synergy: if next item exactly fits the post residual, reward strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual < 10 {
        score += 15.0; // next item can't use this dead space anyway
    }

    // Mean residual coupling: if this bin is far below mean residual, it's a laggard bin; fill it.
    if (bin_residual as f64) < mean_residual - 5.0 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    score
}

