        if slack > 0 && slack < next_item_size as f64 { score -= 8.0 * (1.0 - slack / next_item_size as f64) ; }
    }
    if post_residual > 0 && post_residual < 12 {
        score += 45.0 + 2.0 * (12 - post_residual) as f64 ;
        if next_item_size > post_residual { score += 20.0 ; }
    }
    let diff = (bin_residual as f64 - item_size as f64 - mean_residual) . abs () ;
    score += 0.25 * diff ;
    if fitting_bins_count == 1 && bin_residual < bin_capacity { score -= 50.0 ; }
    if fitting_bins_count > 2 {
        let slack = (bin_residual - item_size) as f64 ;
        score += 0.4 * slack ;
    }
    let progress = step_index as f64 / total_items . max (1) as f64 ;
    if progress < 0.4 { score += 0.25 * post_residual as f64 ; }
    else if progress > 0.85 { score += 0.5 * post_residual as f64 ; }
    if bin_residual == bin_capacity {
        score += 20.0 - 20.0 * (1.0 - progress) ;
        if fitting_bins_count == 0 { score -= 600.0 ; }
        else if item_size > bin_capacity / 2 && fitting_bins_count <= 2 { score -= 80.0 ; }
        else {
            let waste = (bin_residual - item_size) as f64 ;
            let nxt = next_item_size . max (1) as f64 ;
            if waste > 0.0 && waste < nxt { score -= 150.0 * (1.0 - waste / nxt) ; }
            else if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 { score += 30.0 + 0.3 * post_residual as f64 ; }
            else if item_size <= bin_capacity / 4 { score += 45.0 ; }
            else if waste > nxt as f64 { score += 25.0 ; }
        }
        if fitting_bins_count > 0 && mean_residual > item_size as f64 + 10.0 { score += 35.0 ; }
    }
    let dead = post_residual as f64 / bin_capacity as f64 ;
    if dead > 0.0 {
        let ideal = if next_item_size > 0 { next_item_size as f64 / bin_capacity as f64 } else { 0.0 } ;
        if dead < 0.35 { score += 105.0 * (0.35 - dead) ; }
        else if dead < 0.6 { let target = ideal . clamp (0.35 , 0.6) ; score += 25.0 + 60.0 * (dead - target) . abs () ; }
        else if dead < 0.85 { score += 8.0 ; }
    }
    if fitting_bins_count > 1 && next_item_size > 0 && post_residual == next_item_size { score -= 45.0 * (1.0 - progress) ; }
    if progress > 0.7 && open_bins_count > 4 {
        let fill = 1.0 - bin_residual as f64 / bin_capacity as f64 ;
        score -= 45.0 * fill ;
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size . min (item_size . max (1)) { score += 12.0 ; }
    if post_residual == item_size { score -= 85.0 ; }
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 6 { score -= 60.0 ; }
    if next_item_size > 0 && post_residual > next_item_size && post_residual < next_item_size + item_size { score += 18.0 ; }
    if post_residual > 0 && post_residual <= 4 { score += 30.0 ; }
    if next_item_size > 0 && item_size > 0 && post_residual >= next_item_size {
        let rem = post_residual - next_item_size ;
        if rem > 0 && rem < item_size && rem < 8 { score += 10.0 + 2.0 * (8 - rem) as f64 ; }
    }
    if fitting_bins_count == 1 && bin_residual < bin_capacity { score -= 40.0 ; }
    if next_item_size > 0 && post_residual > 0 {
        let gap = post_residual . saturating_sub (next_item_size) as f64 ;
        if gap > 0.0 && gap < 14.0 { score += 2.6 * (14.0 - gap) ; }
    }
    let fill_ratio = 1.0 - (bin_residual . saturating_sub (item_size)) as f64 / bin_capacity as f64 ;
    if fill_ratio > 0.9 { score -= 15.0 * (fill_ratio - 0.9) * 10.0 ; }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 1.5 * (next_item_size - post_residual) as f64 ;
        let miss = (next_item_size - post_residual) as f64 ;
        if miss <= 6.0 { score += 3.0 * miss * (1.0 + progress) ; }
    }
    if progress > 0.9 { score += 0.8 * post_residual as f64 ; }
    if fitting_bins_count == 1 && bin_residual != bin_capacity { score -= 18.0 ; }
    if progress > 0.75 && open_bins_count > 3 { score += 0.35 * (bin_residual . saturating_sub (item_size)) as f64 ; }
    // new mutation: penalize bins whose post-residual can only hold tiny items when better fits exist
    if fitting_bins_count > 1 && post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += 20.0 * (1.0 - progress) ;
    }
    // reward near-perfect two-step closure: residual after next item is exactly item_size
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size == item_size { score -= 35.0 ; }
    let score = score * 0.95 + diff * 0.05 ;
    let score = score * 0.95 + ((1.0 - (bin_residual . saturating_sub (item_size)) as f64 / bin_capacity as f64) as f64) * 0.05 ;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
