pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let frac = post_residual as f64 / bin_capacity as f64;
    score += frac * frac * 40.0;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Harmonic class: bins whose residual is small (<= 10) are nearly closed;
    // placing here "closes" a bin cleanly.
    if post_residual <= 10 {
        score -= 15.0;
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // otherwise we open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing fits are bad.
    if bin_residual == bin_capacity {
        score += 30.0;
        // But if next item is large and this bin is fresh, opening may be fine.
        if next_item_size > 0 && next_item_size <= bin_capacity {
            let pair = item_size + next_item_size;
            if pair > bin_capacity {
                // New bin lets next item land here too when pair doesn't fit elsewhere;
                // mildly reduce penalty.
                score -= 10.0;
            }
        }
    }

    // Lookahead: if next item fits exactly in the post_residual, big bonus.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item fits but leaves more waste; scale reward by tightness.
        let next_fit = (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 12.0 * (1.0 - next_fit);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here: penalize leaving a residual that traps space.
        score += 8.0;
    }

    // Modulo/harmonic classes on post_residual: residuals in [1,10] are the
    // most valuable "almost closed" states; mid-range residuals (30..60) are
    // flexible, large residuals (>60) waste potential.
    let cls = post_residual / 10;
    match cls {
        0 => score -= 10.0,
        1 | 2 => score -= 4.0,
        3 | 4 | 5 => score -= 2.0,
        6 | 7 => score += 5.0,
        _ => score += 10.0,
    }

    // Early in the stream, allow more bins to spread items (better future packing).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity && progress < 0.2 {
        score -= 5.0;
    }

    // Many open bins with high mean residual: prefer consolidating into
    // existing bins rather than opening more.
    if open_bins_count > 4 && mean_residual > 30.0 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are nearly useless.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Tightness coupling: reward small post_residual relative to mean residual.
    score -= (mean_residual - post_residual as f64) * 0.15;

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.6;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a new bin unless it enables a great fit.
    if bin_residual == bin_capacity {
        score += 25.0 + open_bins_count as f64 * 0.3;
        if post_residual as i64 - next_item_size as i64 == 0 {
            score -= 80.0; // new bin perfectly sized for the lookahead item
        }
    }

    // Lookahead synergy: reward leaving space exactly usable by the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
        if post_residual == next_item_size {
            score -= 20.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        score += 6.0; // gap cannot host the next item
    }

    // Early stream: be slightly more willing to open bins for flexibility.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), scaled against mean residual.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // 2-step lookahead: reward exact match of next item into post_residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack_after_next = post_residual - next_item_size;
        score -= 25.0 * (1.0 - slack_after_next as f64 / bin_capacity as f64);
        if slack_after_next == 0 {
            score -= 30.0; // perfect 2-item chain fill
        }
    } else if next_item_size > 0 {
        // Next item cannot follow in this bin: penalize proportionally to dead space.
        score += 10.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Relative-to-mean coupling: bins with residual below mean are precious; placing
    // a large item there is good, leaving them unused wastes them.
    let resid = bin_residual as f64;
    if resid < mean_residual {
        score -= 8.0 * (mean_residual - resid) / bin_capacity as f64;
    } else {
        score += 4.0 * (resid - mean_residual) / bin_capacity as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: make it attractive only when the item is huge relative to
    // capacity or no good fit exists; otherwise keep it mildly unattractive.
    if bin_residual == bin_capacity {
        score += 35.0;
        if item_size > bin_capacity * 3 / 4 {
            score -= 25.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size {
            score -= 15.0; // next item likely needs a fresh bin anyway
        }
    }

    // Late in the stream, close out bins aggressively: avoid stranding small residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 12.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Many open bins: prefer consolidating into already-open bins.
    score += 2.0 * open_bins_count as f64 * 0.05 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual)
    score -= (bin_capacity as f64 - post_residual as f64).powi(2) / (bin_capacity as f64).powi(2) * 20.0;

    // Penalize dead space: post residual that is too small to hold typical items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 5.0;
    }

    // Perfect pairing: post_residual exactly matches next item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    // Time horizon: early in stream, be more willing to open new bins; later, consolidate
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin_penalty = 10.0 * (1.0 - progress);
    if bin_residual == bin_capacity {
        score += new_bin_penalty;
        // Opening new bin is attractive if mean residual is small (existing bins nearly full)
        score -= (mean_residual / bin_capacity as f64) * 8.0;
    } else {
        // Prefer fuller bins relative to mean residual
        if (bin_residual as f64) < mean_residual {
            score -= 6.0;
        } else {
            score += 3.0;
        }
    }

    // Penalize proliferation of open bins when item is small
    if item_size < 30 && open_bins_count > 3 {
        score += (open_bins_count as f64) * 0.5;
    }

    // Reward using bins that already have low residual relative to capacity (fill them up)
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= fill_ratio * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64) / (total_items as f64).max(1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Base: prefer small post residual (tight fit), with non-linear shaping
    let mut score = 1.0 - (1.0 - x).powi(3);
    score = score * cap;

    // Smooth polynomial coupling of post residual with stream progress:
    // early on, tolerate larger residuals; later, penalize them more strongly.
    let coupling = x * x * (0.5 + 1.5 * progress) - 2.0 * x * progress;
    score += 40.0 * coupling;

    // Penalize dead space that likely cannot fit the next item (smooth hinge)
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0) / cap;
        score += 25.0 * gap * gap * (1.0 + progress);
        // Reward if next item fits snugly
        let snug = (pr - next_item_size as f64).max(0.0) / cap;
        score -= 15.0 * (1.0 - snug) * (pr >= next_item_size as f64) as i32 as f64;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0 * (1.0 - progress);
    }

    // Mild penalty relative to mean residual: avoid wasting well-filled bins
    score += 3.0 * (mean_residual - pr) / cap;

    // New-bin candidate: neutral-ish baseline, penalized mildly as bins accumulate
    if bin_residual == bin_capacity {
        score = cap * (0.6 + 0.4 * (1.0 - progress)) + 2.0 * (open_bins_count as f64).ln();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" the leftover space is.
    // Class boundaries at multiples of 10 (typical item granularity) and 25.
    let post = post_residual;
    let class10 = (post / 10) as f64;
    let rem10 = (post % 10) as f64;
    let rem25 = (post % 25) as f64;

    // Reward residuals that fall into "harmonic" classes (divisible by 10 or 25):
    // these are likely to be exactly filled by future items.
    if rem10 == 0.0 && post > 0 {
        score -= 8.0 + class10 * 2.0;
    }
    if rem25 == 0.0 && post > 0 {
        score -= 6.0;
    }
    // Penalize awkward dead space: small nonzero remainders are nearly unusable
    // (items are >= 1, but sub-10 fragments rarely match typical sizes).
    if post > 0 && post < 10 {
        score += 12.0;
    }
    // Integer-division threshold: leftover in [10,20) is a "good class" if it
    // can host the lookahead item exactly.
    if next_item_size > 0 {
        let nxt = next_item_size;
        if nxt == post {
            score -= 20.0; // perfect lookahead fit
        } else if nxt < post {
            let nxt_post = post - nxt;
            if nxt_post % 10 == 0 || nxt_post % 25 == 0 {
                score -= 7.0;
            }
            score += (nxt_post % 10) as f64 * 0.5;
        } else {
            // lookahead cannot follow in this bin: mild penalty unless bin is fresh
            score += 4.0;
        }
    }

    // Modulo coupling between item size and capacity: items that leave residuals
    // in the same harmonic family as themselves pack well.
    if (item_size % 25) == (post % 25) && post > 0 {
        score -= 3.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless residual becomes tiny dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if post >= 10 {
            score -= 15.0;
        } else {
            score += 5.0;
        }
    }

    // New-bin candidate handling: an empty bin is a fallback. Make it attractive
    // only when no open bin offers a tight fit.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Base cost of a fresh bin; large so tight fits in open bins win.
        score = cap * 0.9;
        // Later in the stream, or when mean residual is large, opening a new bin
        // is more expensive (we should consolidate).
        score += progress * 10.0 + (mean_residual / cap) * 15.0;
        // Perfect-fit classes for the current item in a fresh bin are cheap.
        if item_size % 10 == 0 {
            score -= 5.0;
        }
        if next_item_size > 0 && (item_size + next_item_size) as u32 % 100 == bin_capacity {
            score -= 30.0; // fresh bin can host item + lookahead exactly
        }
    }

    // Mild global pressure: prefer filling bins when many are open.
    score -= (open_bins_count as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.16;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 18.0;
    }

    // Reward tight fits (post_residual near zero but usable).
    if post_residual == 0 {
        score -= 25.0;
    }

    // Dead space is worse if no future item can fill it.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.8;
    }

    // Reward bins whose residual closely matches the next item (lookahead chaining).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: penalize creating new bins when many bins are open.
    if bin_residual == bin_capacity {
        score += 10.0 + open_bins_count as f64 * 2.5;
        // But allow a new bin if current bin would leave a bad gap.
        if post_residual < 10 && post_residual > 0 {
            score -= 40.0;
        }
    }

    // Mild preference for bins below mean residual (consolidating space).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * 30.0;

    // 2-step lookahead: reward when next item exactly fills post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 100.0; // perfect chaining
        } else if next_item_size <= post_residual {
            // next fits: reward proportional to how well it matches
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize dead space more strongly
            let gap = (next_item_size - post_residual) as f64;
            score += gap.min(bin_capacity as f64) * 0.8;
        }
    }

    // Compare post_residual against mean residual: leaving residual far below
    // mean creates unusable space relative to the fleet average
    let mean_gap = (post_residual as f64 - mean_residual) / bin_capacity as f64;
    score += mean_gap * 15.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalty for wasting a large residual on a small item when many bins are open
    if post_residual > item_size * 2 && open_bins_count > 1 {
        score += 8.0;
    }

    // Late in the stream: consolidate aggressively, discourage new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses or when item fits elsewhere
        score += 20.0 + 40.0 * progress;
        if fitting_bins_count > 0 {
            score += 30.0;
        }
    }

    // Slight bonus for bins that remain balanced with the fleet
    score -= (mean_residual - post_residual as f64).abs() * -0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
