    // Many open bins: encourage filling them rather than opening more.
    if open_bins_count > 3 {
        score -= 2.0 * (open_bins_count.min(20) as f64) * (1.0 - progress);
    }

    // Large items: prefer bins where they leave a workable residual (~ small gap).
    let ideal_gap = 20.0;
    let gap_err = ((post_residual as f64) - ideal_gap).abs();
    score += 0.15 * gap_err;

    score
}

