pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: dead space buckets
    // Class 0: post_residual == 0 (perfect fit) -> strong reward
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // classify residual into harmonic buckets via integer division
        let cls = post_residual / 10; // 0..=10
        // small residuals (<20) are near-useless dead space; penalize mildly
        match cls {
            0 => score += 18.0,                    // 1..9: dead space
            1 => score += 10.0,                    // 10..19
            2 => score += 4.0,                     // 20..29
            3 | 4 => score -= 3.0,                 // 30..49 useful
            5 | 6 => score -= 6.0,                 // 50..69
            _ => score -= 8.0,                     // 70+: very reusable
        }
        // modulo arithmetic: residuals divisible by common item sizes are valuable
        if post_residual % 10 == 0 { score -= 4.0; }
        if post_residual % 20 == 0 { score -= 3.0; }
        if post_residual % 25 == 0 { score -= 2.0; }
        if post_residual % 5 == 0 { score -= 1.0; }
    }

    // Lookahead coupling: does post_residual fit the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
            // exact harmonic match: next item exactly fills remaining space
            if post_residual == next_item_size { score -= 15.0; }
        } else if next_item_size > bin_residual {
            // next item won't fit anywhere in this bin regardless; residual value matters less
            score -= 2.0;
        } else {
            // next item fits this bin now but not after placement -> creates stranded space
            score += 6.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: keep empty bins attractive only when current fit is poor
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 35.0;
        // open fewer bins early in the stream
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 * (1.0 - progress);
        // if many open bins already fit the item, opening new is wasteful
        if fitting_bins_count > 0 {
            score += 12.0 * (fitting_bins_count as f64).min(5.0);
        }
        // if item is large relative to capacity, prefer existing tight fits anyway
        if item_size * 4 >= bin_capacity * 3 {
            score += 10.0;
        }
    }

    // Slight preference for tighter existing bins (fill ratio coupling)
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 6.0 * fill;

    // Mean residual context: when open bins are generally loose, prioritize tight fits more
    if mean_residual > 30.0 && post_residual < mean_residual {
        score -= 4.0;
    }

    // Small open-bins count pressure: avoid bin proliferation
    score += 1.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest plausible future item (<= 10) are pure waste; penalize hard.
    if post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 8.0;
    } else if post_residual == 0 {
        // Perfect fit is ideal: strong reward.
        score -= 60.0;
    } else {
        // Smooth penalty for small-but-usable gaps that may become dead space.
        let tightness = 1.0 - (post_residual as f64) / 20.0;
        if post_residual < 20 {
            score += tightness * 12.0;
        }
    }

    // Reward bins whose residual can still accommodate the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
            // Bonus if post-residual is a tight, efficient host for next item.
            let slack = post_residual - next_item_size;
            if slack <= 8 {
                score -= 10.0;
            }
        } else {
            // Post residual cannot host next item: mild penalty scaled by gap.
            let gap = next_item_size - post_residual;
            score += (gap as f64).min(40.0) * 0.4;
        }
    }

    // Open-bin pressure: discourage spreading across many open bins when
    // this placement leaves a poor residual; encourage compacting.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (1.0 + mean_residual.max(1.0) / 10.0);
    score += pressure * (0.5 + 0.5 * progress);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless post residual is dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity && post_residual >= 10 {
        score -= 25.0;
    }

    // New-bin candidate: make empty bins attractive only when no open bin
    // offers a decent fit (i.e., all fits would leave dead space).
    if bin_residual == bin_capacity {
        // Neutral baseline slightly worse than a good existing fit.
        score = 25.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // New bin can host next item fully: slight edge.
            score -= 5.0;
        }
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual and next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match => strongly favored; near matches partially rewarded.
        score -= 60.0 * (1.0 - diff / (bin_capacity as f64)).exp() * (if diff == 0 { 2.0 } else { 1.0 });

        // Penalize leaving residuals slightly larger than next item (unusable dead space for lookahead).
        if post_residual < next_item_size {
            // Next item can't follow here; mild penalty proportional to gap.
            score += 0.5 * (next_item_size - post_residual) as f64;
        } else if post_residual > next_item_size {
            // Dead space left after the lookahead placement.
            score += 0.3 * (post_residual - next_item_size) as f64;
        }
    }

    // Relative-to-mean-residual matching: bins with residual near mean are "typical";
    // prefer bins whose residual is close to the item need relative to average slack.
    let mean_gap = (bin_residual as f64 - mean_residual).abs();
    score += 0.2 * mean_gap;

    // Last-chance bonus: if this is the only bin that fits, strongly avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin; reduced when many bins are open and fragmented.
        score += 25.0 + 2.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // A fresh bin perfectly fits the next item too; soften penalty.
            let d = (bin_capacity as i64 - next_item_size as i64).abs() as f64;
            score -= 30.0 * (1.0 - d / (bin_capacity as f64)).exp();
        }
    }

    // Late in the stream, tighten packing (dead space matters more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.5;

    score
}

