pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Normalized post-residual (0..1)
    let post_n = post / cap;

    // Base: post residual, but its importance grows as stream progresses
    // (later waste matters more because fewer chances to fill gaps).
    let base = post * (1.0 + 1.5 * progress * progress);

    // Non-linear penalty for awkward residuals: quadratic coupling of
    // post-residual with item size (big items leaving big gaps are bad).
    let awkward = 0.8 * post_n * post_n * (item / cap) * cap;

    // Reward tight fits: smooth term favoring small post_residual relative to item.
    let tight_bonus = -2.0 * (item / (post + item + 1.0)) * cap * (1.0 - progress);

    // Last-chance bonus: strongly favor this bin if it's the only fitting one.
    let last_chance = if fitting_bins_count == 1 { -50.0 } else { 0.0 };

    // Lookahead: penalize if next item would not fit the post-residual,
    // scaled smoothly by how much slack is lost.
    let lookahead = if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx > post {
            0.5 * (nx - post) * (1.0 + progress)
        } else {
            -0.3 * post_n * nx
        }
    } else {
        0.0
    };

    // Mean-residual coupling: prefer bins near the mean residual (smooth Gaussian-ish)
    let diff = post - mean_residual;
    let mean_coupling = 0.05 * diff * diff / (1.0 + progress);

    base + awkward + tight_bonus + last_chance + lookahead + mean_coupling
}

