 if progress > 0.7 && open_bins_count > 4 { let fill = 1.0 - bin_residual as f64 / bin_capacity as f64 ; score -= 30.0 * fill ; } if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size { score += 1.5 * (next_item_size - post_residual) as f64 ; } if progress > 0.9 { score += 0.8 * post_residual as f64 ; } if bin_residual == bin_capacity && fitting_bins_count > 0 { let best_waste = (bin_residual - item_size) as f64 ; if item_size <= bin_capacity / 4 { score += 45.0 ; } else if best_waste > next_item_size as f64 { score += 25.0 ; } } if bin_residual == bin_capacity { score += 18.0 ; score -= 20.0 * (1.0 - progress) ; } if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size { let unreachable = next_item_size as f64 - post_residual as f64 ; score += 0.8 * unreachable * (1.0 - 0.5 * progress) ; } if next_item_size > 0 && post_residual >= next_item_size { let slack = post_residual - next_item_size ; if slack > 0 && slack < next_item_size { score -= 6.0 * (1.0 - slack as f64 / next_item_size as f64) ; } } let score = score * 0.95 + ((step_index as f64 / total_items . max (1) as f64) as f64) * 0.05 ; if next_item_size > 0 && post_residual > 0 { let gap = post_residual . saturating_sub (next_item_size) as f64 ; if gap > 0.0 && gap < 14.0 { score += 2.6 * (14.0 - gap) ; } } if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size { let miss = (next_item_size - post_residual) as f64 ; if miss <= 6.0 { score += 3.0 * miss * (1.0 + progress) ; } } if progress > 0.75 && open_bins_count > 3 { score += 0.35 * (bin_residual . saturating_sub (item_size)) as f64 ; } if progress > 0.9 { score += 0.8 * post_residual as f64 ; } if next_item_size > 0 && item_size > 0 && post_residual >= next_item_size { let rem = post_residual - next_item_size ; if rem > 0 && rem < item_size && rem < 8 { score += 10.0 + 2.0 * (8 - rem) as f64 ; } } if next_item_size > 0 && post_residual >= next_item_size { let leftover = post_residual - next_i